const uid = () => Math.random().toString(36).slice(2, 9);
const fmt = (n) =>
  (isNaN(n) ? 0 : n).toLocaleString("en-US", {
    style: "currency",
    currency: "USD",
  });
const num = (v) => {
  const n = parseFloat(v);
  return isNaN(n) ? 0 : n;
};

// "$1,355.99" -> 1355.99
const parseMoney = (v) => {
  if (typeof v === "number") return v;
  if (!v) return 0;
  const n = parseFloat(String(v).replace(/[^0-9.-]/g, ""));
  return isNaN(n) ? 0 : n;
};

// "51h 44min" / "7h 46min" / "0min" / "8" / "8.5" -> decimal hours
const parseDuration = (v) => {
  if (typeof v === "number") return v;
  if (!v) return 0;
  const s = String(v).trim();
  const h = s.match(/(\d+(?:\.\d+)?)\s*h/i);
  const m = s.match(/(\d+(?:\.\d+)?)\s*m/i);
  if (h || m) {
    return (h ? parseFloat(h[1]) : 0) + (m ? parseFloat(m[1]) / 60 : 0);
  }
  const plain = parseFloat(s.replace(/[^0-9.]/g, ""));
  return isNaN(plain) ? 0 : plain;
};

// ---------- saved data ----------
// A downloaded page keeps its data in this browser, under this key.
const STORE_KEY = "spicysweet.payroll.v2";
// stamped by build.py; the hosted page checks version.json so a stale cached copy
// offers a reload instead of silently staying old
const APP_VERSION = (typeof window !== "undefined" && window.SPICY_VERSION) || "dev";
function UpdateWatcher() {
  const [fresh, setFresh] = useState(null);
  useEffect(() => {
    if (APP_VERSION === "dev" || !/^https?:/.test(window.location.protocol)) return;
    let stop = false;
    const check = async () => {
      try {
        const r = await fetch("version.json?t=" + Date.now(), { cache: "no-store" });
        if (!r.ok) return;
        const j = await r.json();
        if (!stop && j && j.version && j.version !== APP_VERSION) setFresh(j.version);
      } catch (err) {}
    };
    check();
    const t = setInterval(check, 3 * 60 * 1000);
    const vis = () => document.visibilityState === "visible" && check();
    document.addEventListener("visibilitychange", vis);
    return () => {
      stop = true;
      clearInterval(t);
      document.removeEventListener("visibilitychange", vis);
    };
  }, []);
  if (!fresh) return null;
  return (
    <div className="ss-update ss-pop print:hidden" role="status">
      <span><b>Update ready</b> · {fresh} is out, you're on {APP_VERSION}.</span>
      <button
        onClick={() => {
          const u = new URL(window.location.href);
          u.searchParams.set("v", fresh);
          window.location.replace(u.toString());
        }}
        className="ss-btn ss-btn-primary py-1.5"
      >
        Reload now
      </button>
    </div>
  );
}

