const applyTheme = (t, prefs = SFX_PREFS) => {
  try {
    const el = document.documentElement;
    const theme = THEMES.some(([id]) => id === t) ? t : "light";
    el.setAttribute("data-theme", theme);
    const bg = prefs.bg && /^#[0-9a-f]{6}$/i.test(prefs.bg) ? prefs.bg : "";
    const ac = prefs.accent && /^#[0-9a-f]{6}$/i.test(prefs.accent) ? prefs.accent : "";
    // light or dark text follows the background actually on screen, not the theme's name
    const themeBg = (THEMES.find(([id]) => id === theme) || THEMES[0])[3][0];
    const lum = hexLum(bg || themeBg);
    const dark = lum != null && lum < 0.3;
    el.setAttribute("data-mode", dark ? "dark" : "light");
    if (bg) {
      el.style.setProperty("--user-bg", bg);
      // glass surfaces tinted from the background so cards never clash with it
      el.style.setProperty("--user-card", dark ? shade(bg, 0.1) : shade(bg, 0.6));
      el.style.setProperty("--user-glass", dark ? "rgba(255,255,255,.07)" : "rgba(255,255,255,.62)");
      // a gentle diagonal gradient built from the chosen colour: a warmer, lighter
      // corner and a cooler, deeper one
      el.style.setProperty("--user-bg2", dark ? shade(bg, 0.08) : shade(bg, 0.35));
      el.style.setProperty("--user-bg3", dark ? shade(bg, -0.3) : shade(bg, -0.06));
    } else {
      el.style.removeProperty("--user-bg");
      el.style.removeProperty("--user-card");
      el.style.removeProperty("--user-glass");
      el.style.removeProperty("--user-bg2");
      el.style.removeProperty("--user-bg3");
    }
    if (ac) {
      el.style.setProperty("--user-accent", ac);
      // text uses of the accent must clear 4.5:1 against the surface it sits on
      let txt = ac;
      const surface = dark ? "#2A1A36" : "#FFFFFF";
      for (let i = 0; i < 8 && contrast(txt, surface) < 4.5; i++) txt = shade(txt, dark ? 0.12 : -0.12);
      el.style.setProperty("--user-accent-text", txt);
      // and white text on the accent (buttons) needs the same
      let btn = ac;
      for (let i = 0; i < 8 && contrast("#FFFFFF", btn) < 4.5; i++) btn = shade(btn, -0.1);
      el.style.setProperty("--user-accent-btn", btn);
    } else {
      ["--user-accent", "--user-accent-text", "--user-accent-btn"].forEach((k) => el.style.removeProperty(k));
    }
    el.setAttribute("data-custom-bg", bg ? "1" : "0");
    el.setAttribute("data-custom-accent", ac ? "1" : "0");
    el.style.setProperty("--orb-a", String(prefs.glow == null ? 1 : Math.max(0, Math.min(1, num(prefs.glow)))));
  } catch (err) {}
};
