// "" = follow whatever zone this computer is set to
const browserTz = () => {
  try {
    return Intl.DateTimeFormat().resolvedOptions().timeZone || "UTC";
  } catch (err) {
    return "UTC";
  }
};
const tzOf = (settings) => (settings && settings.timeZone) || browserTz();
const tzValid = (tz) => {
  if (!tz) return false;
  try {
    new Intl.DateTimeFormat("en-CA", { timeZone: tz }).format(new Date());
    return true;
  } catch (err) {
    return false;
  }
};
const TZ_CHOICES = [
  ["", "Automatic — this computer"],
  ["America/New_York", "Eastern — New York"],
  ["America/Chicago", "Central — Chicago"],
  ["America/Denver", "Mountain — Denver"],
  ["America/Phoenix", "Arizona — Phoenix"],
  ["America/Los_Angeles", "Pacific — Los Angeles"],
  ["America/Anchorage", "Alaska — Anchorage"],
  ["Pacific/Honolulu", "Hawaii — Honolulu"],
  ["Asia/Manila", "Philippines — Manila"],
  ["Asia/Kolkata", "India — Kolkata"],
  ["Asia/Dubai", "Gulf — Dubai"],
  ["Europe/London", "UK — London"],
  ["Europe/Berlin", "Central Europe — Berlin"],
  ["UTC", "UTC"],
];
// today's date in the chosen zone, as YYYY-MM-DD (never the UTC date)
const todayStr = (settings) => {
  try {
    const parts = new Intl.DateTimeFormat("en-CA", {
      timeZone: tzOf(settings),
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
    }).formatToParts(new Date());
    const get = (t) => (parts.find((x) => x.type === t) || {}).value || "";
    const y = get("year"),
      m = get("month"),
      d = get("day");
    if (y && m && d) return `${y}-${m}-${d}`;
  } catch (err) {}
  return new Date().toISOString().slice(0, 10);
};
// the same moment, written the way the reader's locale writes dates
const todayPretty = (settings) => {
  try {
    return new Date().toLocaleDateString(undefined, {
      timeZone: tzOf(settings),
    });
  } catch (err) {
    return new Date().toLocaleDateString();
  }
};

// "2026-06-30 00:00:00 - 2026-06-30 23:59:59" -> "2026-06-30"
const parseDateRange = (v) => {
  if (!v) return "";
  const m = String(v).match(/\d{4}-\d{2}-\d{2}/);
  return m ? m[0] : "";
};

const round2 = (n) => Math.round(n * 100) / 100;

// "4m 38s" / "1h 2m" -> minutes
const parseRespMinutes = (v) => {
  if (!v) return 0;
  const s = String(v);
  const h = s.match(/(\d+)\s*h/i);
  const m = s.match(/(\d+)\s*m/i);
  const sec = s.match(/(\d+)\s*s/i);
  return (h ? +h[1] * 60 : 0) + (m ? +m[1] : 0) + (sec ? +sec[1] / 60 : 0);
};

