function getTier(revenue, tiers) {
  let t = -1;
  tiers.forEach((tier, i) => {
    if (revenue >= tier.threshold) t = i;
  });
  return t;
}

// a team's targets: its override if set, otherwise the default targets
const tiersFor = (settings, team) =>
  (team && settings.teamTiers && settings.teamTiers[team]) || settings.tiers;
const withTeamTiers = (settings, team) => ({
  ...settings,
  tiers: tiersFor(settings, team),
});

// base pay fields that can be overridden per team and per chatter
const BASE_FIELDS = [
  ["baseRate", "Base hourly rate ($)", "0.25"],
  ["baseCommission", "Base commission (%)", "0.5"],
  ["streamingBump", "Streaming bump ($/hr)", "0.25"],
  ["headChatterFlat", "Head chatter pay ($/wk)", "1"],
  ["weeklyBonus", "Weekly goal bonus ($)", "1"],
  ["monthlyBonus", "Monthly goal bonus ($)", "1"],
];
const BASE_KEYS = BASE_FIELDS.map((f) => f[0]);
const isSet = (v) => v !== undefined && v !== null && v !== "";

// strikes still on the clock: the log when it's on, else the plain number
function activeStrikes(e, settings) {
  if (LIVE_FEATURES.strikeLog && Array.isArray(e.strikeLog)) {
    const days = num(settings && settings.strikeExpiryDays);
    const now = Date.now();
    return e.strikeLog.filter((s) => {
      if (!days) return true; // 0 = strikes never expire
      const t = Date.parse((s.date || "") + "T00:00:00");
      if (isNaN(t)) return true;
      return (now - t) / 86400000 <= days;
    }).length;
  }
  return Math.max(0, Math.floor(num(e.strikes)));
}

// agency default -> team override -> individual override
function resolveSettings(settings, emp) {
  const team = emp ? emp.team || "" : "";
  const teamOv = (team && settings.teamBase && settings.teamBase[team]) || {};
  const empOv = (emp && emp.payOverride) || {};
  const out = {
    ...settings,
    tiers:
      emp && emp.tierOverride && emp.tierOverride.length
        ? emp.tierOverride
        : tiersFor(settings, team),
  };
  BASE_KEYS.forEach((k) => {
    if (isSet(teamOv[k])) out[k] = num(teamOv[k]);
    if (isSet(empOv[k])) out[k] = num(empOv[k]);
  });
  return out;
}

// value to show in the settings panel for a scope ("" = agency default)
function baseValueFor(settings, team, field) {
  const teamOv = (team && settings.teamBase && settings.teamBase[team]) || {};
  return isSet(teamOv[field]) ? teamOv[field] : settings[field];
}

// does this team / chatter have any custom pay set?
const teamHasCustom = (settings, team) =>
  !!(settings.teamTiers[team] ||
    (settings.teamBase &&
      settings.teamBase[team] &&
      Object.keys(settings.teamBase[team]).length));
const empHasCustom = (e) =>
  !!(
    (e.payOverride && Object.keys(e.payOverride).length) ||
    (e.tierOverride && e.tierOverride.length)
  );

// full weekly totals for one chatter (used by the UI and the PDF export)
function calcEmployee(e, settings, prize) {
  const es = resolveSettings(settings, e);
  // strike penalties: 2+ = no weekly bonus, 4+ = no monthly bonus, 6+ = -1% commission
  const strikes = activeStrikes(e, settings);
  const commissionPenalty = strikes >= 6 ? 1 : 0;
  const weeklyForfeited = strikes >= 2;
  const monthlyForfeited = strikes >= 4;
  const shiftCalcs = e.shifts.map((s) =>
    calcShift(s, es, e.headChatter, commissionPenalty)
  );
  const hourlyTotal = shiftCalcs.reduce((a, c) => a + c.hourlyPay, 0);
  const commissionTotal = shiftCalcs.reduce((a, c) => a + c.commissionPay, 0);
  const weeklyBonusCount = e.weeklyGoals.filter(Boolean).length;
  const headChatterPay = e.headChatter ? es.headChatterFlat : 0;
  const weeklyBonusPay = weeklyForfeited
    ? 0
    : weeklyBonusCount * es.weeklyBonus;
  const monthlyBonusPay =
    !e.monthlyGoal || monthlyForfeited ? 0 : es.monthlyBonus;
  const bonusTotal = weeklyBonusPay + monthlyBonusPay;
  const adjustments = (LIVE_FEATURES.adjustments !== false ? e.adjustments || [] : []).filter(
    (a) => num(a.amount) !== 0
  );
  const adjustTotal = adjustments.reduce((a, x) => a + num(x.amount), 0);
  const totalHours = round2(shiftCalcs.reduce((a, c) => a + c.hours, 0));
  const totalRevenue = shiftCalcs.reduce((a, c) => a + c.revenue, 0);
  const totalNetRevenue = shiftCalcs.reduce((a, c) => a + c.netRevenue, 0);
  return {
    shiftCalcs,
    hourlyTotal,
    commissionTotal,
    weeklyBonusCount,
    headChatterPay,
    weeklyBonusPay,
    monthlyBonusPay,
    bonusTotal,
    strikes,
    commissionPenalty,
    weeklyForfeited,
    monthlyForfeited,
    prizeAmount: prize ? prize.amount : 0,
    prizeRank: prize ? prize.rank : 0,
    prizeLabel: prize ? prize.label : "",
    adjustments,
    adjustTotal,
    gross:
      hourlyTotal +
      commissionTotal +
      bonusTotal +
      headChatterPay +
      adjustTotal +
      (prize ? prize.amount : 0),
    totalHours,
    totalRevenue,
    totalNetRevenue,
  };
}

