function trainingFor(title) {
  const hit = CHATTER_TRAINING.find(([k]) => title.startsWith(k));
  return hit ? hit[1] : null;
}
function chatterTrainingPlan(ins) {
  const steps = [];
  if (ins && ins.tips.length) {
    ins.tips.forEach((t) => {
      const s = trainingFor(t.t);
      if (s) s.forEach((x) => steps.indexOf(x) === -1 && steps.push(x));
    });
  }
  if (!steps.length)
    return [
      "Keep running the playbook that worked this week.",
      "Write down your best conversation and reuse the structure.",
      "Pick one stretch goal — the next target tier — and chase it.",
    ];
  return steps.slice(0, 5);
}

// snapshot of a finished week, saved to disk for next week's comparison
function buildWeekSnapshot(employees, settings, prevWeek) {
  const prizeMap = leaderboardPrizes(employees, settings, prevWeek);
  const chatters = {};
  employees.forEach((e) => {
    const c = calcEmployee(e, settings, prizeMap[e.id]);
    const ins = buildInsights(e, employees, settings);
    const worked = c.shiftCalcs.filter((k) => k.hours > 0 || k.revenue > 0);
    if (!worked.length) return;
    chatters[e.name.trim().toLowerCase()] = {
      name: e.name,
      team: e.team || "",
      rev: c.totalRevenue,
      gross: c.gross,
      hours: c.totalHours,
      shifts: worked.length,
      hits: worked.filter((k) => k.tier >= 0).length,
      rph: c.totalHours ? c.totalRevenue / c.totalHours : 0,
      ppv: e.shifts.reduce((a, s) => a + num(s.ppvSent), 0),
      msgs: e.shifts.reduce((a, s) => a + num(s.msgsSent), 0),
      avgResp: ins ? ins.avgResp : null,
      avgRev: worked.length ? c.totalRevenue / worked.length : 0,
      gr: ins ? ins.goldenRatio : null,
      unlock: ins ? ins.unlockRate : null,
      strikes: c.strikes,
      focus: ins ? ins.tips.map((t) => t.t) : [],
      net: round2(c.totalNetRevenue),
      bonus: round2(c.weeklyBonusPay + c.monthlyBonusPay),
      prize: round2(c.prizeAmount),
      adjust: round2(c.adjustTotal),
      head: round2(c.headChatterPay),
    };
  });
  const dates = employees
    .flatMap((e) => e.shifts.map((s) => s.date))
    .filter((d) => /^\d{4}-\d{2}-\d{2}$/.test(d))
    .sort();
  const teams = {};
  [...TEAM_DEFS.map((t) => t.team), ""].forEach((team) => {
    const r = buildTeamReport(team, employees, settings);
    if (!r) return;
    const payroll = employees
      .filter((e) => (e.team || "") === team)
      .reduce((a, e) => a + calcEmployee(e, settings, prizeMap[e.id]).gross, 0);
    const shiftRevs = [];
    employees
      .filter((e) => (e.team || "") === team)
      .forEach((e) => {
        calcEmployee(e, settings, prizeMap[e.id]).shiftCalcs.forEach((k) => {
          if (k.revenue > 0) shiftRevs.push(round2(k.revenue));
        });
      });
    teams[team || "Unassigned"] = {
      shiftRevs,
      rev: r.totalRev,
      payroll,
      rph: r.teamRph,
      avgShift: r.teamAvgShift,
      hours: r.totalHours,
      hits: r.totalHits,
      shifts: r.totalShifts,
      ppv: r.teamPpv,
      gr: r.teamGr,
      unlock: r.teamUnlockRate,
      resp: r.avgRespTeam,
      members: r.members.length,
    };
  });
  const models = {};
  const mr = buildModelReport(employees, settings);
  if (mr) {
    mr.rows.forEach((r) => {
      models[r.name] = { rev: round2(r.revenue), hours: round2(r.hours), shifts: round2(r.shifts) };
    });
  }
  return {
    type: "spicysweet-week",
    savedAt: new Date().toISOString(),
    savedDate: todayStr(settings),
    timeZone: tzOf(settings),
    payPeriod: settings.payPeriod || "",
    weekStart: dates[0] || "",
    weekEnd: dates[dates.length - 1] || "",
    chatters,
    teams,
    models,
    // everything needed to reopen this week later
    full: { employees, settings, roster: LIVE_ROSTER || DEFAULT_ROSTER, prizes: prizeMap },
  };
}
// the month a saved week belongs to ("2026-10"), oldest-shift-first
const snapMonth = (h) => {
  const d = (h && (h.weekStart || h.savedDate || (h.savedAt || "").slice(0, 10))) || "";
  return d.slice(0, 7);
};
const monthLabel = (ym) => {
  if (!ym) return "";
  const [y, m] = ym.split("-").map(Number);
  return new Date(y, m - 1, 1).toLocaleString("en-US", { month: "long", year: "numeric" });
};
// everything saved in one calendar month, plus the week on screen if it belongs there
function buildMonthRollup(history, currentSnap, ym) {
  const weeks = (history || []).filter((h) => snapMonth(h) === ym);
  if (currentSnap && snapMonth(currentSnap) === ym && !weeks.some((h) => h.weekStart && h.weekStart === currentSnap.weekStart)) {
    weeks.push({ ...currentSnap, live: true });
  }
  weeks.sort((a, b) => (a.weekStart || a.savedDate || "").localeCompare(b.weekStart || b.savedDate || ""));
  const tot = { rev: 0, net: 0, payroll: 0, bonus: 0, prize: 0, adjust: 0, hours: 0, shifts: 0 };
  const teams = {};
  const models = {};
  const chatters = {};
  weeks.forEach((h) => {
    Object.values(h.chatters || {}).forEach((c) => {
      tot.rev += c.rev || 0;
      tot.net += c.net != null ? c.net : (c.rev || 0) * 0.8;
      tot.payroll += c.gross || 0;
      tot.bonus += c.bonus || 0;
      tot.prize += c.prize || 0;
      tot.adjust += c.adjust || 0;
      tot.hours += c.hours || 0;
      tot.shifts += c.shifts || 0;
      const k = (c.name || "").trim().toLowerCase();
      const row = (chatters[k] = chatters[k] || { name: c.name, team: c.team || "", rev: 0, gross: 0, weeks: 0, hits: 0, shifts: 0 });
      row.rev += c.rev || 0; row.gross += c.gross || 0; row.weeks += 1; row.hits += c.hits || 0; row.shifts += c.shifts || 0;
      if (!row.team && c.team) row.team = c.team;
    });
    Object.entries(h.teams || {}).forEach(([team, t]) => {
      const row = (teams[team] = teams[team] || { team, rev: 0, payroll: 0, weeks: 0 });
      row.rev += t.rev || 0; row.payroll += t.payroll || 0; row.weeks += 1;
    });
    Object.entries(h.models || {}).forEach(([m, v]) => {
      models[m] = (models[m] || 0) + (v.rev || 0);
    });
  });
  return {
    ym,
    weeks,
    tot,
    teams: Object.values(teams).sort((a, b) => b.rev - a.rev),
    models: Object.entries(models).map(([model, rev]) => ({ model, rev })).sort((a, b) => b.rev - a.rev),
    chatters: Object.values(chatters).sort((a, b) => b.rev - a.rev),
  };
}

// which of the four "Week N" goal boxes a week belongs to, from its first shift date
const weekIndexOf = (dateStr) => {
  if (!dateStr) return -1;
  const day = Number(dateStr.slice(8, 10));
  if (!day) return -1;
  return Math.min(3, Math.floor((day - 1) / 7));
};

