const DECK = {
  PINK: "DB2777",
  ROSE: "F43F5E",
  SOFT: "FBCFE8",
  BLUSH: "FFF1F5",
  TINT: "FCE7F3",
  DARK: "1E293B",
  GRAY: "64748B",
  WHITE: "FFFFFF",
  UP: "059669",
  DOWN: "DC2626",
  AMBER: "B45309",
  YELLOW: "FEF3C7",
  FONT: "Arial",
};

// "▲ $312 (+8%)" style comparison against last week
function deltaChip(cur, prev, opts) {
  const o = opts || {};
  if (prev === null || prev === undefined || isNaN(prev))
    return { text: "no data last week", color: DECK.GRAY };
  const diff = cur - prev;
  const pct = prev !== 0 ? (diff / Math.abs(prev)) * 100 : null;
  if (Math.abs(diff) < (o.eps || 0.005))
    return { text: "same as last week", color: DECK.GRAY };
  const up = diff > 0;
  const good = o.invert ? !up : up;
  const shown = o.money
    ? fmt(Math.abs(diff))
    : Math.abs(diff).toFixed(o.dp === undefined ? 1 : o.dp) + (o.suffix || "");
  return {
    text:
      (up ? "\u25B2 " : "\u25BC ") +
      shown +
      (pct !== null && Math.abs(pct) >= 1
        ? ` (${up ? "+" : "-"}${Math.abs(pct).toFixed(0)}%)`
        : "") +
      " vs last week",
    color: good ? DECK.UP : DECK.DOWN,
  };
}

// rough height (inches) a bulleted text box needs
function estBoxH(items, wIn, fs, spacePt) {
  const perLine = Math.max(20, (wIn * 96) / (fs * 0.52));
  const lines = items.reduce(
    (a, t) => a + Math.max(1, Math.ceil(String(t).length / perLine)),
    0
  );
  return lines * ((fs * 1.35) / 72) + items.length * ((spacePt || 0) / 72);
}

function buildDeckData(team, employees, settings, prevWeek) {
  const report = buildTeamReport(team, employees, settings);
  if (!report) return null;
  const prizeMap = leaderboardPrizes(employees, settings, prevWeek);
  const payroll = employees
    .filter((e) => (e.team || "") === team)
    .reduce((a, e) => a + calcEmployee(e, settings, prizeMap[e.id]).gross, 0);
  const key = team || "Unassigned";
  return {
    team: key,
    emoji: teamEmoji(team),
    report,
    payroll,
    prev: prevWeek && prevWeek.teams ? prevWeek.teams[key] || null : null,
    prevChatters: (prevWeek && prevWeek.chatters) || {},
    prevPeriod: (prevWeek && prevWeek.payPeriod) || "",
  };
}

