// agency-wide rollup of every team report
function buildAgencyReport(employees, settings, prevWeek) {
  const prizeMap = leaderboardPrizes(employees, settings, prevWeek);
  const teams = [...TEAM_DEFS.map((t) => t.team), ""]
    .map((team) => {
      const report = buildTeamReport(team, employees, settings);
      const payroll = employees
        .filter((e) => (e.team || "") === team)
        .reduce(
          (a, e) => a + calcEmployee(e, settings, prizeMap[e.id]).gross,
          0
        );
      return { team: team || "Unassigned", report, payroll };
    })
    .filter((t) => t.report);
  if (!teams.length) return null;
  const sum = (f) => teams.reduce((a, t) => a + f(t.report), 0);
  const totalRev = sum((r) => r.totalRev);
  const totalHours = sum((r) => r.totalHours);
  const totalShifts = sum((r) => r.totalShifts);
  const totalHits = sum((r) => r.totalHits);
  const totalPpv = sum((r) => r.teamPpv);
  const totalMsgs = sum((r) => r.teamMsgs);
  const totalPayroll = teams.reduce((a, t) => a + t.payroll, 0);
  const chatterCount = teams.reduce((a, t) => a + t.report.members.length, 0);
  const gr = totalMsgs > 0 ? (totalPpv / totalMsgs) * 100 : null;
  const topTeam = [...teams].sort(
    (a, b) => b.report.totalRev - a.report.totalRev
  )[0];
  const allMembers = teams.flatMap((t) =>
    t.report.members.map((m) => ({ m, team: t.team }))
  );
  const topChatter = [...allMembers].sort((a, b) => b.m.rev - a.m.rev)[0];
  return {
    teams,
    totalRev,
    totalHours,
    totalShifts,
    totalHits,
    totalPpv,
    gr,
    totalPayroll,
    chatterCount,
    topTeam,
    topChatter,
  };
}

// multi-page All Chatters Insights PDF
function makeAgencyPdf(rep, settings, dateStr) {
  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({ unit: "mm", format: "a4" });
  const L = 14,
    R = 196,
    WIDTH = R - L;
  let y = 0;
  const ensure = (need = 10) => {
    if (y > 285 - need) {
      doc.addPage();
      y = 18;
    }
  };
  const wrapText = (text, size, rgb, opts = {}) => {
    doc.setFont("helvetica", opts.bold ? "bold" : "normal");
    doc.setFontSize(size);
    doc.setTextColor(rgb[0], rgb[1], rgb[2]);
    const lines = doc.splitTextToSize(text, WIDTH - (opts.indent || 0));
    lines.forEach((ln) => {
      ensure(6);
      doc.text(ln, L + (opts.indent || 0), y);
      y += size * 0.5;
    });
    y += opts.after != null ? opts.after : 1.5;
  };
  const heading = (text) => {
    ensure(14);
    y += 3;
    wrapText(text, 13, [219, 39, 119], { bold: true, after: 2.5 });
  };
  // header band
  doc.setFillColor(219, 39, 119);
  doc.rect(0, 0, 210, 30, "F");
  try {
    doc.addImage(LOGO, "PNG", R - 46, 4.5, 46, 21.3);
  } catch (err) {}
  doc.setTextColor(255, 255, 255);
  doc.setFont("helvetica", "normal");
  doc.setFontSize(8);
  doc.text("ALL CHATTERS INSIGHTS REPORT", L, 11);
  doc.setFont("helvetica", "bold");
  doc.setFontSize(16);
  doc.text(settings.companyName, L, 19);
  doc.setFont("helvetica", "normal");
  doc.setFontSize(8);
  doc.text(
    (settings.payPeriod ? "Pay period " + settings.payPeriod + "  ·  " : "") +
      "Generated " + dateStr,
    L,
    25.5
  );
  y = 40;
  // overall summary
  heading("Overall performance summary");
  wrapText(
    `${rep.chatterCount} chatters across ${rep.teams.length} teams worked ${rep.totalShifts} shifts (${round2(rep.totalHours)} hours clocked).`,
    9.5,
    [15, 23, 42]
  );
  wrapText(
    `Revenue generated: ${fmt(rep.totalRev)}   ·   Total payroll cost: ${fmt(rep.totalPayroll)}   ·   Revenue per payroll dollar: ${rep.totalPayroll > 0 ? "$" + (rep.totalRev / rep.totalPayroll).toFixed(2) : "—"}`,
    9.5,
    [15, 23, 42]
  );
  wrapText(
    `Targets hit on ${rep.totalHits} of ${rep.totalShifts} shifts   ·   ${rep.totalPpv} PPVs sent` +
      (rep.gr != null ? `   ·   Agency golden ratio ${rep.gr.toFixed(1)}%` : ""),
    9.5,
    [15, 23, 42]
  );
  wrapText(
    `Top team: ${rep.topTeam.team} (${fmt(rep.topTeam.report.totalRev)})   ·   Top earner: ${rep.topChatter.m.e.name}, ${rep.topChatter.team} (${fmt(rep.topChatter.m.rev)})`,
    9.5,
    [15, 23, 42],
    { after: 3 }
  );
  // payroll by team table
  heading("Payroll cost by team");
  rep.teams.forEach((t) => {
    ensure(6);
    doc.setFont("helvetica", "normal");
    doc.setFontSize(9.5);
    doc.setTextColor(15, 23, 42);
    doc.text(`${t.team}  (${t.report.members.length} chatters)`, L, y);
    doc.setFont("helvetica", "bold");
    doc.text(fmt(t.payroll), R, y, { align: "right" });
    y += 5.5;
  });
  ensure(8);
  doc.setDrawColor(244, 194, 219);
  doc.line(L, y - 2, R, y - 2);
  doc.setFont("helvetica", "bold");
  doc.setFontSize(10.5);
  doc.setTextColor(15, 23, 42);
  doc.text("All chatters combined", L, y + 3);
  doc.setTextColor(219, 39, 119);
  doc.text(fmt(rep.totalPayroll), R, y + 3, { align: "right" });
  y += 10;
  // per-team pages
  rep.teams.forEach((t) => {
    const r = t.report;
    doc.addPage();
    y = 18;
    wrapText(`${t.team}`, 15, [219, 39, 119], { bold: true, after: 1 });
    wrapText(
      `Revenue ${fmt(r.totalRev)} · Payroll ${fmt(t.payroll)} · ${fmt(r.teamRph)}/hr · avg ${fmt(r.teamAvgShift)}/shift · targets ${r.totalHits}/${r.totalShifts} · ${round2(r.totalHours)}h clocked · ${r.teamPpv} PPVs` +
        (r.teamGr != null ? ` · GR ${r.teamGr.toFixed(1)}%` : "") +
        (r.teamUnlockRate != null
          ? ` · unlock ${r.teamUnlockRate.toFixed(0)}%`
          : "") +
        (r.avgRespTeam != null
          ? ` · team avg response ${r.avgRespTeam.toFixed(1)} min`
          : ""),
      8.5,
      [100, 116, 139],
      { after: 3 }
    );
    heading("Chatter rankings");
    r.members.forEach((m, i) => {
      ensure(14);
      wrapText(
        `${i + 1}. ${m.e.name}${m.e.headChatter ? " (head chatter)" : ""} — ${fmt(m.rev)}`,
        9.5,
        [15, 23, 42],
        { bold: true, after: 0.5 }
      );
      wrapText(
        `${fmt(m.rph)}/hr · ${fmt(m.avgRev)}/shift · ${m.hits}/${m.shifts} targets · ${round2(m.hours)}h clocked · ${m.ppv} PPVs` +
          (m.msgs > 0 ? ` · GR ${((m.ppv / m.msgs) * 100).toFixed(1)}%` : "") +
          (m.ins && m.ins.avgResp != null
            ? ` · ${m.ins.avgResp.toFixed(1)} min response`
            : "") +
          (m.c.strikes ? ` · ${m.c.strikes} strikes` : ""),
        8.5,
        [100, 116, 139],
        { indent: 4, after: m.topTip ? 0.5 : 2 }
      );
      if (m.topTip) {
        wrapText(`Focus: ${m.topTip}`, 8.5, [217, 119, 6], {
          indent: 4,
          after: 2,
        });
      }
    });
    heading("What this team is doing well");
    r.wins.forEach((w) => wrapText("• " + w, 9.5, [15, 23, 42]));
    const activeFlags = FLAG_ORDER.filter((k) =>
      k === "strikers" ? r.flags.strikers.length > 0 : r.flags[k]
    );
    heading("Main areas underperforming");
    if (activeFlags.length) {
      activeFlags.forEach((k) =>
        wrapText(
          "• " +
            FLAG_LABELS[k] +
            (k === "strikers" ? ` (${r.flags.strikers.join(", ")})` : ""),
          9.5,
          [15, 23, 42]
        )
      );
    } else {
      wrapText("• No major weaknesses flagged this week.", 9.5, [15, 23, 42]);
    }
    heading("Recommendations");
    r.tips.forEach((tip) => wrapText("• " + tip, 9.5, [15, 23, 42]));
    heading("Individual improvement areas");
    r.members.forEach((m) => {
      ensure(12);
      wrapText(
        m.e.name +
          (m.e.headChatter ? " (head chatter)" : "") +
          (m.c.strikes ? ` — ${m.c.strikes} strikes` : ""),
        10,
        [15, 23, 42],
        { bold: true, after: 0.5 }
      );
      if (m.ins && m.ins.tips.length) {
        m.ins.tips.forEach((tip) =>
          wrapText(`• ${tip.t}: ${tip.b}`, 9, [15, 23, 42], { indent: 3 })
        );
      } else {
        wrapText(
          "• No red flags this week — keep doing what's working.",
          9,
          [100, 116, 139],
          { indent: 3 }
        );
      }
      y += 1.5;
    });
    heading("Training guide for " + t.team);
    const modules = activeFlags.length
      ? activeFlags.map((k) => TRAINING_MODULES[k])
      : [TRAINING_MODULES.maintain];
    modules.forEach((mod) => {
      ensure(16);
      wrapText(mod.title, 11, [15, 23, 42], { bold: true, after: 0.5 });
      wrapText("Why: " + mod.why, 8.5, [100, 116, 139], { after: 1.5 });
      mod.steps.forEach((s, i) =>
        wrapText(`${i + 1}. ${s}`, 9.5, [15, 23, 42], { indent: 3 })
      );
      y += 2;
    });
  });
  return doc;
}

// what a chatter earned the agency against what they cost
function marginFor(calc) {
  const kept = calc.totalNetRevenue; // after the platform's cut
  const cost = calc.gross; // everything we pay them
  return { kept, cost, margin: kept - cost, ratio: cost > 0 ? kept / cost : null };
}

// year-to-date earnings, from stored weeks plus the week on screen
function ytdFor(name, history, currentGross, settings) {
  const key = (name || "").trim().toLowerCase();
  const year = todayStr(settings).slice(0, 4);
  let total = 0;
  let weeks = 0;
  (history || []).forEach((h) => {
    const when = (h.savedDate || h.savedAt || "").slice(0, 4);
    if (when && when !== year) return;
    const c = h.chatters && h.chatters[key];
    if (c && c.gross) {
      total += c.gross;
      weeks += 1;
    }
  });
  return { total: total + (currentGross || 0), weeks: weeks + 1 };
}

// week-by-week series for one chatter, or for the agency
function buildTrend(history, currentSnap, name) {
  const pts = [];
  const push = (snap, label) => {
    if (!snap) return;
    if (name) {
      const c = snap.chatters && snap.chatters[name.trim().toLowerCase()];
      if (!c) return;
      pts.push({
        label,
        rev: c.rev || 0,
        gross: c.gross || 0,
        hits: c.hits || 0,
        shifts: c.shifts || 0,
        gr: c.gr == null ? null : c.gr,
        rph: c.rph || 0,
      });
    } else {
      const all = Object.values(snap.chatters || {});
      if (!all.length) return;
      pts.push({
        label,
        rev: all.reduce((a, c) => a + (c.rev || 0), 0),
        gross: all.reduce((a, c) => a + (c.gross || 0), 0),
        hits: all.reduce((a, c) => a + (c.hits || 0), 0),
        shifts: all.reduce((a, c) => a + (c.shifts || 0), 0),
        gr: null,
        rph: 0,
      });
    }
  };
  (history || []).forEach((h, i) =>
    push(h, h.payPeriod || h.savedDate || "wk " + (i + 1))
  );
  push(currentSnap, "this week");
  return pts;
}

// ---------- pasted Discord messages ----------
// Chatters report Fansly earnings at the end of a shift, in whatever words they
// like. This reads a whole week of pasted messages and pulls out who, when and
// how much. Everything it finds is shown for checking before anything is applied.
const NO_EARNINGS = /\b(none|nothing|no fansly|zero|nada|n\/?a|didn'?t get any|no sales)\b/i;

function shiftDate(settings, offsetDays) {
  const base = new Date();
  base.setDate(base.getDate() - (offsetDays || 0));
  try {
    const parts = new Intl.DateTimeFormat("en-CA", {
      timeZone: tzOf(settings),
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
    }).formatToParts(base);
    const g = (t) => (parts.find((x) => x.type === t) || {}).value || "";
    const y = g("year"), m = g("month"), d = g("day");
    if (y && m && d) return `${y}-${m}-${d}`;
  } catch (err) {}
  return base.toISOString().slice(0, 10);
}

// "11/01/2026", "1/5/26", "Today at 8:04 PM", "Yesterday", "2026-11-01"
function parseMsgDate(text, settings) {
  const s = String(text || "");
  if (/\btoday\b/i.test(s)) return shiftDate(settings, 0);
  if (/\byesterday\b/i.test(s)) return shiftDate(settings, 1);
  let m = s.match(/(\d{4})-(\d{2})-(\d{2})/);
  if (m) return `${m[1]}-${m[2]}-${m[3]}`;
  m = s.match(/\b(\d{1,2})\/(\d{1,2})(?:\/(\d{2,4}))?\b/);
  if (m) {
    const mm = String(+m[1]).padStart(2, "0");
    const dd = String(+m[2]).padStart(2, "0");
    let yy = m[3] ? +m[3] : +shiftDate(settings, 0).slice(0, 4);
    if (yy < 100) yy += 2000;
    if (+mm >= 1 && +mm <= 12 && +dd >= 1 && +dd <= 31)
      return `${yy}-${mm}-${dd}`;
  }
  return "";
}

// the money in a message, ignoring clock times and dates
function parseMsgAmount(text) {
  let s = String(text || "");
  s = s.replace(/\b\d{1,2}:\d{2}(:\d{2})?\s*(am|pm)?\b/gi, " "); // 8:04 PM
  s = s.replace(/\b\d{1,2}\/\d{1,2}(\/\d{2,4})?\b/g, " "); // 11/01/2026
  s = s.replace(/\b\d{4}-\d{2}-\d{2}\b/g, " "); // 2026-11-01
  const money = (v) => {
    const n = parseFloat(String(v).replace(/,/g, ""));
    return isNaN(n) ? null : n;
  };
  let m = s.match(/\$\s*([\d,]+(?:\.\d{1,2})?)/); // $250.50
  if (m) return money(m[1]);
  m = s.match(/([\d,]+(?:\.\d{1,2})?)\s*(?:usd|dollars?|bucks)\b/i);
  if (m) return money(m[1]);
  m = s.match(/fansly[^0-9a-z]{0,12}([\d,]+(?:\.\d{1,2})?)/i); // fansly: 250
  if (m) return money(m[1]);
  m = s.match(/([\d,]+(?:\.\d{1,2})?)[^0-9a-z]{0,12}(?:on\s+)?fansly/i); // 250 on fansly
  if (m) return money(m[1]);
  if (NO_EARNINGS.test(s) && /fansly/i.test(s)) return 0;
  const bare = s.match(/(?:^|\s)([\d,]+(?:\.\d{1,2})?)(?=\s|$)/g);
  if (bare && bare.length === 1) return money(bare[0]);
  return null;
}

function parseFanslyPaste(text, employees, settings) {
  const known = employees
    .map((e) => ({ id: e.id, name: (e.name || "").trim() }))
    .filter((e) => e.name);
  const matchName = (raw) => {
    const n = String(raw || "")
      .replace(/[(\[].*?[)\]]/g, "") // drop (they/them), [BOT]
      .replace(/[^A-Za-z0-9 _.'-]/g, "")
      .trim()
      .toLowerCase();
    if (!n) return null;
    let hit = known.find((k) => k.name.toLowerCase() === n);
    if (hit) return hit;
    hit = known.find((k) => {
      const kn = k.name.toLowerCase();
      if (n.length < 3) return false;
      return kn.startsWith(n) || n.startsWith(kn) || n.split(" ")[0] === kn;
    });
    return hit || null;
  };

  const lines = String(text || "").split(/\r?\n/);
  const rows = [];
  let who = null;
  let when = "";
  const looksLikeTime = (s) =>
    /\d{1,2}:\d{2}|\bam\b|\bpm\b|today|yesterday|\d{1,2}\/\d{1,2}|\d{4}-\d{2}-\d{2}/i.test(s);
  // a line that is ONLY a timestamp — once the date and time are removed,
  // next to nothing is left. "had 12 fans chat me today" is not one of these.
  const isTimestampOnly = (s) => {
    if (!looksLikeTime(s)) return false;
    const left = String(s)
      .replace(/\d{1,2}:\d{2}(:\d{2})?/g, " ")
      .replace(/\b(am|pm)\b/gi, " ")
      .replace(/\b(today|yesterday|at|on)\b/gi, " ")
      .replace(/\d{1,2}\/\d{1,2}(\/\d{2,4})?/g, " ")
      .replace(/\d{4}-\d{2}-\d{2}/g, " ")
      .replace(/[—–\-,.]/g, " ")
      .replace(/\s+/g, "");
    return left.length <= 3;
  };

  lines.forEach((raw) => {
    let line = String(raw).replace(/\u200b/g, "").trim();
    if (!line) return;
    let body = line;

    // [11/01/2026 8:04 PM] Keycee: fansly 250
    let m = line.match(/^\[([^\]]+)\]\s*([^:]{1,40}):\s*(.*)$/);
    if (m) {
      const hit = matchName(m[2]);
      if (hit) who = hit;
      const d = parseMsgDate(m[1], settings);
      if (d) when = d;
      body = m[3];
    } else {
      // Keycee — Today at 8:04 PM   (a Discord message header)
      m = line.match(/^(.{1,40}?)\s*[—–]\s*(.+)$/);
      if (m && looksLikeTime(m[2]) && matchName(m[1])) {
        who = matchName(m[1]);
        const d = parseMsgDate(m[2], settings);
        if (d) when = d;
        body = "";
      } else {
        // Keycee: 250
        m = line.match(/^([^:]{1,40}):\s*(.*)$/);
        if (m && matchName(m[1])) {
          who = matchName(m[1]);
          body = m[2];
        } else if (matchName(line) && !/\d/.test(line)) {
          // a bare name on its own line
          who = matchName(line);
          body = "";
        } else if (isTimestampOnly(line) && !/\$|fansly/i.test(line)) {
          const d = parseMsgDate(line, settings);
          if (d) when = d;
          body = "";
        }
      }
    }

    if (!body.trim()) return;
    const amount = parseMsgAmount(body);
    if (amount === null) return;
    const d2 = parseMsgDate(body, settings);
    // a line that says "$" or "fansly" is almost certainly a report;
    // anything else ("12 fans chatted me") is offered but left unticked
    const confident = /\$|fansly/i.test(body) || NO_EARNINGS.test(body);
    rows.push({
      id: uid(),
      name: who ? who.name : "",
      empId: who ? who.id : "",
      date: d2 || when,
      amount,
      line: line.slice(0, 120),
      confident,
      use: !!who && confident,
    });
  });
  return rows;
}

// where a parsed row would land, and whether that shift already has a figure
function planFanslyRows(rows, employees) {
  return rows.map((r) => {
    const emp = employees.find((e) => e.id === r.empId);
    if (!emp) return { ...r, status: "no-chatter" };
    const worked = emp.shifts.filter(
      (s) => num(s.hours) > 0 || num(s.revenue) > 0
    );
    let shift = r.date ? emp.shifts.find((s) => s.date === r.date) : null;
    if (!shift && !r.date && worked.length === 1) shift = worked[0];
    if (!shift) return { ...r, status: r.date ? "no-shift" : "no-date" };
    return {
      ...r,
      shiftId: shift.id,
      existing: num(shift.fansly),
      status: num(shift.fansly) > 0 ? "overwrite" : "ok",
    };
  });
}

// things worth looking at before any money moves
function buildChecks(employees, settings, prevWeek, prizes) {
  const out = [];
  const add = (level, who, text) => out.push({ level, who, text });
  const seen = {};
  const prior = (prevWeek && prevWeek.chatters) || null;
  const here = {};

  employees.forEach((e) => {
    const name = (e.name || "").trim();
    const key = name.toLowerCase();
    if (!name) {
      add("warn", "—", "A chatter has no name.");
    } else {
      if (seen[key]) add("error", name, "Appears twice — pay would be duplicated.");
      seen[key] = true;
      here[key] = true;
    }
    const c = calcEmployee(e, settings, prizes ? prizes[e.id] : null);
    const worked = c.shiftCalcs.filter((k) => k.hours > 0 || k.revenue > 0);
    if (!worked.length) {
      if (c.gross > 0)
        add("warn", name, `No shifts entered, but ${fmt(c.gross)} would still be paid.`);
      return;
    }
    if (!e.team) add("info", name, "No team set — left out of team reports.");

    c.shiftCalcs.forEach((k, i) => {
      const s = e.shifts[i];
      const label = (s && s.date) || `shift ${i + 1}`;
      if (k.revenue > 0 && k.hours === 0)
        add("error", name, `${label}: ${fmt(k.revenue)} revenue with 0 hours clocked.`);
      if (k.hours > 24)
        add("error", name, `${label}: ${round2(k.hours)} hours in one shift — more than a day.`);
      else if (k.hours > 16)
        add("info", name, `${label}: ${round2(k.hours)}h — looks like a picked-up shift (double).`);
      if (k.revenue < 0 || k.hours < 0)
        add("error", name, `${label}: negative numbers.`);
      if (!s || !s.date)
        add("info", name, `Shift ${i + 1} has no date.`);
    });

    if (c.totalHours > 90)
      add("warn", name, `${round2(c.totalHours)} hours this week — more than 90.`);
    const mpH = e.shifts.reduce((a, s) => a + num(s.mpHours), 0);
    if (mpH > 0 && c.totalHours > 0 && mpH < c.totalHours * 0.7)
      add("warn", name, `Only ${round2(mpH)}h of ${round2(c.totalHours)}h clocked were on Messages Pro (${((mpH / c.totalHours) * 100).toFixed(0)}% — below 70%).`);

    if (prior) {
      const p = prior[key];
      if (p && p.rev > 0) {
        const ratio = c.totalRevenue / p.rev;
        if (ratio >= 5)
          add("warn", name, `Revenue is ${ratio.toFixed(1)}× last week (${fmt(p.rev)} → ${fmt(c.totalRevenue)}). Worth confirming.`);
        else if (ratio > 0 && ratio <= 0.25)
          add("warn", name, `Revenue dropped to ${(ratio * 100).toFixed(0)}% of last week (${fmt(p.rev)} → ${fmt(c.totalRevenue)}).`);
      }
    }
  });

  if (prior) {
    Object.keys(prior).forEach((k) => {
      if (!here[k] && prior[k].rev > 0)
        add("warn", prior[k].name || k, "Was in last week's import but is missing from this one.");
    });
  }

  const order = { error: 0, warn: 1, info: 2 };
  out.sort((a, b) => order[a.level] - order[b.level]);
  return {
    items: out,
    errors: out.filter((x) => x.level === "error").length,
    warnings: out.filter((x) => x.level === "warn").length,
  };
}

// compares this week against the focus areas set last week
const FOLLOW_METRICS = [
  ["Golden ratio", "gr", "golden ratio", "%", false],
  ["PPV unlock rate", "unlock", "unlock rate", "%", false],
  ["Response speed", "avgResp", "response time", " min", true],
  ["Revenue per hour", "rph", "revenue per hour", "$", false],
  ["Close the gap", "avgRev", "average per shift", "$", false],
  ["Push to Target", "avgRev", "average per shift", "$", false],
  ["Consistency", "avgRev", "average per shift", "$", false],
  ["Hours & attendance", "hours", "hours clocked", "h", false],
  ["Strike recovery", "strikes", "strikes", "", true],
];
function buildFollowUp(emp, ins, prevWeek, calc) {
  const prior =
    prevWeek &&
    prevWeek.chatters &&
    prevWeek.chatters[(emp.name || "").trim().toLowerCase()];
  if (!prior || !prior.focus || !prior.focus.length) return null;
  const nowVals = {
    gr: ins ? ins.goldenRatio : null,
    unlock: ins ? ins.unlockRate : null,
    avgResp: ins ? ins.avgResp : null,
    rph: ins ? ins.rph : null,
    avgRev: ins ? ins.avgRev : null,
    hours: calc ? calc.totalHours : null,
    strikes: calc ? calc.strikes : null,
  };
  const out = [];
  prior.focus.forEach((title) => {
    const hit = FOLLOW_METRICS.find(([k]) => String(title).startsWith(k));
    if (!hit) return;
    const [, key, label, unit, lowerBetter] = hit;
    const before = prior[key];
    const after = nowVals[key];
    if (before == null || after == null || isNaN(before) || isNaN(after)) {
      out.push({ title, text: `${label} — no comparable number`, state: "flat" });
      return;
    }
    const f = (v) =>
      unit === "$" ? fmt(v) : round2(v) + unit;
    const diff = after - before;
    const better = lowerBetter ? diff < 0 : diff > 0;
    const same = Math.abs(diff) < (unit === "%" ? 0.2 : 0.05);
    out.push({
      title,
      text: `${label} ${f(before)} → ${f(after)}`,
      state: same ? "flat" : better ? "up" : "down",
    });
  });
  return out.length ? out : null;
}

// which models earn best per chatter-hour.
// A shift covering several models can't be split exactly, so its revenue and
// hours are shared evenly between them — an estimate, labelled as one.
function buildModelReport(employees, settings) {
  const models = {};
  let split = false;
  employees.forEach((e) => {
    const c = calcEmployee(e, settings);
    e.shifts.forEach((s, i) => {
      const k = c.shiftCalcs[i];
      if (!k || (k.revenue === 0 && k.hours === 0)) return;
      const names = String(s.creators || "")
        .split(",")
        .map((x) => x.trim())
        .filter(Boolean);
      const list = names.length ? names : ["Unattributed"];
      if (names.length > 1) split = true;
      const share = 1 / list.length;
      list.forEach((nm) => {
        const row = (models[nm] = models[nm] || {
          name: nm,
          revenue: 0,
          of: 0,
          fansly: 0,
          net: 0,
          hours: 0,
          shifts: 0,
          chatters: {},
        });
        row.revenue += k.revenue * share;
        row.of += (k.ofRevenue || 0) * share;
        row.fansly += (k.fanslyRevenue || 0) * share;
        row.net += k.netRevenue * share;
        row.hours += k.hours * share;
        row.shifts += share;
        row.chatters[e.name] = true;
      });
    });
  });
  const rows = Object.values(models)
    .map((r) => ({
      ...r,
      chatterCount: Object.keys(r.chatters).length,
      rph: r.hours > 0 ? r.revenue / r.hours : 0,
    }))
    .sort((a, b) => b.revenue - a.revenue);
  // with a creator report on file, the money comes from Infloww's creator stats
  // (net, scaled to a week) and the chatter sheet only supplies the hours behind it
  const rep = latestCreatorReport(settings);
  if (rep && rep.creators.length) {
    const scale = 7 / (rep.days || 14);
    const key = (x) => String(x || "").trim().toLowerCase();
    const repRows = rep.creators.map((c) => {
      const tagged = rows.find((r) => key(r.name) === key(c.name) || (key(c.name).startsWith(key(r.name)) && key(r.name).length >= 3));
      const revenue = round2(c.total * scale);
      const hours = tagged ? tagged.hours : 0;
      return {
        name: c.name,
        revenue,
        of: revenue,
        fansly: 0,
        net: revenue,
        hours,
        shifts: tagged ? tagged.shifts : 0,
        chatterCount: tagged ? Object.keys(tagged.chatters).length : 0,
        rph: hours > 0 ? revenue / hours : 0,
        periodTotal: c.total,
        message: c.message,
        spenders: c.spenders,
        team: creatorTeamOf(settings, c.name),
      };
    }).sort((a, b) => b.revenue - a.revenue);
    return { rows: repRows, totalRev: repRows.reduce((a, r) => a + r.revenue, 0), split, source: "report", period: periodLabel(rep), days: rep.days };
  }
  if (!rows.length) return null;
  const totalRev = rows.reduce((a, r) => a + r.revenue, 0);
  return { rows, totalRev, split, source: "shifts" };
}

// agency-wide leaderboard (public: no strikes shown)
function buildLeaderboard(employees, settings) {
  return employees
    .map((e) => {
      const c = calcEmployee(e, settings);
      const worked = c.shiftCalcs.filter((k) => k.hours > 0 || k.revenue > 0);
      return {
        e,
        shifts: worked.length,
        rev: c.totalRevenue,
        rph: c.totalHours > 0 ? c.totalRevenue / c.totalHours : 0,
        hits: worked.filter((k) => k.tier >= 0).length,
        ppv: e.shifts.reduce((a, s) => a + num(s.ppvSent), 0),
        msgs: e.shifts.reduce((a, s) => a + num(s.msgsSent), 0),
      };
    })
    .filter((m) => m.shifts > 0)
    .sort((a, b) => b.rev - a.rev);
}

// top-3 weekly leaderboard prizes, keyed by employee id
function leaderboardPrizes(employees, settings, prevWeek) {
  const ranked = buildLeaderboard(employees, settings);
  const amounts = [
    num(settings.prize1),
    num(settings.prize2),
    num(settings.prize3),
  ];
  const medal = ["🥇", "🥈", "🥉"];
  const place = ["1st", "2nd", "3rd"];
  const map = {};
  const add = (id, amount, label, rank) => {
    if (!(amount > 0)) return;
    if (map[id]) {
      map[id] = {
        rank: map[id].rank || rank || 0,
        amount: map[id].amount + amount,
        label: map[id].label + " + " + label,
      };
    } else {
      map[id] = { rank: rank || 0, amount, label };
    }
  };
  ranked.slice(0, 3).forEach((m, i) => {
    if (m.rev > 0)
      add(m.e.id, amounts[i], `${medal[i]} ${place[i]} place`, i + 1);
  });
  if (LIVE_FEATURES.bonusPrizes) {
    // most improved needs last week to compare against
    const prior = (prevWeek && prevWeek.chatters) || null;
    if (prior) {
      let best = null;
      ranked.forEach((m) => {
        const p = prior[m.e.name.trim().toLowerCase()];
        if (!p || !(p.rev > 0)) return;
        const gain = m.rev - p.rev;
        if (gain > 0 && (!best || gain > best.gain)) best = { m, gain };
      });
      if (best) add(best.m.e.id, num(settings.improvedPrize), "🚀 Most improved");
    }
    // best golden ratio, among chatters who actually sent messages
    let gr = null;
    ranked.forEach((m) => {
      if (!(m.msgs > 0) || !(m.ppv > 0)) return;
      const ratio = (m.ppv / m.msgs) * 100;
      if (!gr || ratio > gr.ratio) gr = { m, ratio };
    });
    if (gr) add(gr.m.e.id, num(settings.goldenPrize), "🍬 Best golden ratio");
  }
  return map;
}

function rrect(ctx, x, y, w, h, r) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}

// render the leaderboard as a Discord-ready PNG
function makeLeaderboardPng(ranked, settings, cb) {
  const W = 1080,
    headerH = 220,
    rowH = 96,
    footerH = 80,
    pad = 44;
  const H = headerH + ranked.length * rowH + footerH;
  const cv = document.createElement("canvas");
  cv.width = W;
  cv.height = H;
  const ctx = cv.getContext("2d");
  const img = new Image();
  const draw = (withLogo) => {
    const bg = ctx.createLinearGradient(0, 0, 0, H);
    bg.addColorStop(0, "#241019");
    bg.addColorStop(1, "#140a10");
    ctx.fillStyle = bg;
    ctx.fillRect(0, 0, W, H);
    const hg = ctx.createLinearGradient(0, 0, W, 0);
    hg.addColorStop(0, "#db2777");
    hg.addColorStop(0.55, "#f43f5e");
    hg.addColorStop(1, "#ef4444");
    ctx.fillStyle = hg;
    ctx.fillRect(0, 0, W, headerH - 44);
    ctx.fillStyle = "rgba(255,240,150,0.95)";
    ctx.font = "26px Arial";
    [
      [40, 46],
      [W - 60, 60],
      [130, 140],
      [W / 2 + 150, 40],
    ].forEach(([x, yy]) => ctx.fillText("\u2726", x, yy));
    if (withLogo) {
      const lw = 280;
      const lh = lw * (img.height / img.width);
      ctx.drawImage(img, W - lw - 36, 20, lw, lh);
    }
    ctx.fillStyle = "#ffffff";
    ctx.font = "900 52px Arial";
    ctx.fillText("WEEKLY LEADERBOARD", pad, 90);
    ctx.font = "600 25px Arial";
    ctx.fillStyle = "rgba(255,255,255,0.92)";
    ctx.fillText(
      settings.companyName +
        (settings.payPeriod ? "  \u00B7  " + settings.payPeriod : ""),
      pad + 2,
      130
    );
    const medals = ["\uD83E\uDD47", "\uD83E\uDD48", "\uD83E\uDD49"];
    ranked.forEach((m, i) => {
      const ry = headerH - 24 + i * rowH;
      const ch = rowH - 14;
      const cy = ry + ch / 2;
      ctx.fillStyle = i === 0 ? "rgba(244,114,182,0.18)" : "rgba(255,255,255,0.06)";
      rrect(ctx, pad - 12, ry, W - 2 * (pad - 12), ch, 16);
      ctx.fill();
      if (i === 0) {
        ctx.strokeStyle = "rgba(244,114,182,0.85)";
        ctx.lineWidth = 2.5;
        rrect(ctx, pad - 12, ry, W - 2 * (pad - 12), ch, 16);
        ctx.stroke();
      }
      ctx.textBaseline = "middle";
      if (i < 3) {
        ctx.font = "44px Arial";
        ctx.fillStyle = "#fff";
        ctx.fillText(medals[i], pad + 4, cy + 2);
      } else {
        ctx.fillStyle = "rgba(244,114,182,0.9)";
        ctx.font = "900 32px Arial";
        ctx.fillText("#" + (i + 1), pad + 6, cy);
      }
      ctx.fillStyle = "#ffffff";
      ctx.font = "800 31px Arial";
      ctx.fillText(
        m.e.name + (m.e.headChatter ? " \u2605" : ""),
        pad + 88,
        cy - 15
      );
      ctx.fillStyle = "rgba(255,255,255,0.55)";
      ctx.font = "500 20px Arial";
      ctx.fillText(
        (m.e.team ? teamEmoji(m.e.team) + " " + m.e.team : "Unassigned"),
        pad + 88,
        cy + 19
      );
      ctx.textAlign = "right";
      ctx.fillStyle = "#ff7ab8";
      ctx.font = "900 34px Arial";
      ctx.fillText(fmt(m.rev), W - pad - 4, cy - 15);
      const prizeAmt =
        i < 3
          ? [settings.prize1, settings.prize2, settings.prize3][i] || 0
          : 0;
      ctx.fillStyle = "rgba(255,255,255,0.55)";
      ctx.font = "500 19px Arial";
      ctx.fillText(
        (prizeAmt > 0 ? `WINS ${fmt(prizeAmt)} \u00B7 ` : "") +
          `${fmt(m.rph)}/hr \u00B7 ${m.hits}/${m.shifts} targets` +
          (m.msgs > 0
            ? ` \u00B7 GR ${((m.ppv / m.msgs) * 100).toFixed(1)}%`
            : ""),
        W - pad - 4,
        cy + 19
      );
      ctx.textAlign = "left";
      ctx.textBaseline = "alphabetic";
    });
    ctx.fillStyle = "rgba(255,255,255,0.45)";
    ctx.font = "500 20px Arial";
    ctx.textAlign = "center";
    ctx.fillText(
      "Generated " +
        todayPretty(settings) +
        " \u00B7 keep grinding \u2726",
      W / 2,
      H - 34
    );
    ctx.textAlign = "left";
    cv.toBlob(cb, "image/png");
  };
  img.onload = () => draw(true);
  img.onerror = () => draw(false);
  img.src = LOGO;
}

// one chatter's week as a 1080x1080 card to DM them (private: no strikes, no pay)
function makeChatterCardPng(emp, calc, ins, rank, total, settings, cb) {
  const W = 1080, H = 1080, pad = 64;
  const cv = document.createElement("canvas");
  cv.width = W; cv.height = H;
  const ctx = cv.getContext("2d");
  const img = new Image();
  const worked = calc.shiftCalcs.filter((k) => k.hours > 0 || k.revenue > 0);
  const hits = worked.filter((k) => k.tier >= 0).length;
  const rph = calc.totalHours > 0 ? calc.totalRevenue / calc.totalHours : 0;
  const avg = worked.length ? calc.totalRevenue / worked.length : 0;
  const draw = (withLogo) => {
    const bg = ctx.createLinearGradient(0, 0, 0, H);
    bg.addColorStop(0, "#241019"); bg.addColorStop(1, "#140a10");
    ctx.fillStyle = bg; ctx.fillRect(0, 0, W, H);
    const hg = ctx.createLinearGradient(0, 0, W, 0);
    hg.addColorStop(0, "#db2777"); hg.addColorStop(0.55, "#f43f5e"); hg.addColorStop(1, "#ef4444");
    ctx.fillStyle = hg; ctx.fillRect(0, 0, W, 250);
    ctx.fillStyle = "rgba(255,240,150,0.95)"; ctx.font = "26px Arial";
    [[40, 46], [W - 60, 60], [130, 200], [W / 2 + 150, 40], [W - 200, 170]].forEach(([x, yy]) => ctx.fillText("\u2726", x, yy));
    if (withLogo) { const lw = 260; const lh = lw * (img.height / img.width); ctx.drawImage(img, W - lw - 40, 24, lw, lh); }
    ctx.fillStyle = "rgba(255,255,255,0.85)"; ctx.font = "700 24px Arial";
    ctx.fillText((settings.companyName || "").toUpperCase() + "  \u00B7  WEEKLY STATS", pad, 86);
    ctx.fillStyle = "#fff"; ctx.font = "900 72px Arial";
    ctx.fillText((emp.name || "").toUpperCase() + (emp.headChatter ? " \u2605" : ""), pad, 165);
    ctx.font = "600 26px Arial"; ctx.fillStyle = "rgba(255,255,255,0.92)";
    ctx.fillText(
      (emp.team ? teamEmoji(emp.team) + " " + emp.team : "") + (settings.payPeriod ? "  \u00B7  " + settings.payPeriod : ""),
      pad, 212
    );
    // hero number
    ctx.fillStyle = "rgba(255,255,255,0.55)"; ctx.font = "700 24px Arial";
    ctx.fillText("SALES THIS WEEK", pad, 330);
    ctx.fillStyle = "#ff7ab8"; ctx.font = "900 110px Arial";
    ctx.fillText(fmt(calc.totalRevenue), pad - 4, 440);
    if (rank > 0) {
      ctx.textAlign = "right";
      ctx.fillStyle = "rgba(255,255,255,0.55)"; ctx.font = "700 24px Arial";
      ctx.fillText("AGENCY RANK", W - pad, 330);
      ctx.fillStyle = "#fff"; ctx.font = "900 110px Arial";
      ctx.fillText("#" + rank, W - pad, 440);
      ctx.font = "600 24px Arial"; ctx.fillStyle = "rgba(255,255,255,0.55)";
      ctx.fillText("of " + total, W - pad, 476);
      ctx.textAlign = "left";
    }
    // tiles
    const tiles = [
      ["TARGETS HIT", `${hits}/${worked.length}`],
      ["PER HOUR", fmt(rph)],
      ["AVG / SHIFT", fmt(avg)],
      ["GOLDEN RATIO", ins && ins.goldenRatio != null ? ins.goldenRatio.toFixed(1) + "%" : "\u2014"],
      ["HOURS", calc.totalHours + "h"],
      ["RESPONSE", ins && ins.avgResp != null ? ins.avgResp.toFixed(1) + " min" : "\u2014"],
    ];
    const tw = (W - 2 * pad - 2 * 20) / 3, th = 150;
    tiles.forEach(([label, v], i) => {
      const x = pad + (i % 3) * (tw + 20), y = 520 + Math.floor(i / 3) * (th + 20);
      ctx.fillStyle = i === 0 && hits === worked.length && worked.length ? "rgba(16,185,129,0.18)" : "rgba(255,255,255,0.07)";
      rrect(ctx, x, y, tw, th, 22); ctx.fill();
      ctx.fillStyle = "rgba(255,255,255,0.5)"; ctx.font = "700 20px Arial"; ctx.fillText(label, x + 26, y + 46);
      ctx.fillStyle = "#fff"; ctx.font = "900 48px Arial"; ctx.fillText(v, x + 24, y + 110);
    });
    // one line: top win or focus
    const win = ins && ins.wins && ins.wins[0];
    const tip = ins && ins.tips && ins.tips[0];
    ctx.fillStyle = "rgba(255,255,255,0.75)"; ctx.font = "600 26px Arial";
    const line = win ? "\uD83D\uDC97 " + (typeof win === "string" ? win : win.t || "") : tip ? "\uD83C\uDFAF Focus: " + (tip.t || "") : "";
    if (line) {
      // wrap to two lines max
      const words = line.split(" "); let cur = ""; const lines = [];
      words.forEach((w) => { const t = cur ? cur + " " + w : w; if (ctx.measureText(t).width > W - 2 * pad) { lines.push(cur); cur = w; } else cur = t; });
      if (cur) lines.push(cur);
      lines.slice(0, 2).forEach((l, i) => ctx.fillText(l, pad, 920 + i * 36));
    }
    ctx.fillStyle = "rgba(255,255,255,0.45)"; ctx.font = "500 20px Arial"; ctx.textAlign = "center";
    ctx.fillText("Generated " + todayPretty(settings) + " \u00B7 keep grinding \u2726", W / 2, H - 40);
    ctx.textAlign = "left";
    cv.toBlob(cb, "image/png");
  };
  img.onload = () => draw(true);
  img.onerror = () => draw(false);
  img.src = LOGO;
}

// ---------- attendance: the import vs the roster ----------
const addDays = (iso, n) => {
  const d = new Date(iso + "T00:00:00");
  if (isNaN(d)) return "";
  d.setDate(d.getDate() + n);
  const p = (x) => String(x).padStart(2, "0");
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`;
};
const dayLabel = (iso) => {
  const d = new Date(iso + "T00:00:00");
  return isNaN(d) ? iso : d.toLocaleDateString("en-US", { weekday: "short", day: "numeric" });
};
function buildAttendance(employees, roster, settings) {
  const allDates = employees
    .flatMap((e) => e.shifts.filter((sh) => num(sh.hours) > 0 || num(sh.revenue) > 0).map((sh) => sh.date))
    .filter((d) => /^\d{4}-\d{2}-\d{2}$/.test(d))
    .sort();
  if (!allDates.length) return null;
  const start = allDates[0];
  const days = Array.from({ length: 7 }, (_, i) => addDays(start, i));
  const end = days[6];
  const people = (roster || []).map(rosterRow).filter((r) => r.name.trim() && r.status !== "left");
  const byRoster = {};
  employees.forEach((e) => {
    const r = rosterLookup(e.name, roster);
    if (!r) return;
    const k = r.name.toLowerCase();
    const workedNow = e.shifts.some((sh) => num(sh.hours) > 0 || num(sh.revenue) > 0);
    // two entries for one roster person (a rename, a duplicate): keep the one with shifts
    if (!byRoster[k] || (workedNow && !byRoster[k].shifts.some((sh) => num(sh.hours) > 0 || num(sh.revenue) > 0))) byRoster[k] = e;
  });
  const issues = [];
  const perPerson = people.map((p) => {
    const e = byRoster[p.name.toLowerCase()] || null;
    const worked = e ? e.shifts.filter((sh) => num(sh.hours) > 0 || num(sh.revenue) > 0) : [];
    const dates = new Set(worked.map((sh) => sh.date).filter(Boolean));
    const hours = round2(worked.reduce((a, sh) => a + num(sh.hours), 0));
    const short = worked.filter((sh) => num(sh.hours) > 0 && num(sh.hours) < 6);
    const expected = p.days;
    if (expected > 0) {
      if (!e || !worked.length) {
        issues.push({
          key: `none|${p.name}`, level: "warn", who: p.name, emp: e,
          text: `No shifts in this week's import — ${expected} day${expected === 1 ? "" : "s"} expected.`,
          reason: `No shifts worked, week of ${start}`,
        });
      } else if (worked.length < expected) {
        const missed = expected - worked.length;
        issues.push({
          key: `missed|${p.name}`, level: missed >= 2 ? "warn" : "info", who: p.name, emp: e,
          text: `Worked ${worked.length} of ${expected} scheduled days (${hours}h).`,
          reason: `Missed ${missed} shift${missed === 1 ? "" : "s"}, week of ${start}`,
        });
      }
    }
    short.forEach((sh) =>
      issues.push({
        key: `short|${p.name}|${sh.date}`, level: "info", who: p.name, emp: e,
        text: `Short shift on ${sh.date ? dayLabel(sh.date) : "an undated day"} — ${num(sh.hours)}h clocked.`,
        reason: `Short shift ${sh.date || ""} (${num(sh.hours)}h)`,
      })
    );
    return { p, e, worked: worked.length, expected, hours, dates, short: short.length };
  });
  const teams = TEAM_DEFS.map((t) => {
    const slots = SLOTS.map((slot) => {
      const ppl = perPerson.filter((x) => x.p.team === t.team && x.p.slot === slot);
      const byDay = days.map((d) => ppl.filter((x) => x.dates.has(d)).map((x) => x.p.name));
      const gaps = ppl.length ? byDay.filter((names) => names.length === 0).length : 0;
      return { slot, people: ppl.map((x) => x.p.name), byDay, gaps };
    });
    return { team: t.team, emoji: t.emoji, slots, has: slots.some((sl) => sl.people.length) };
  }).filter((t) => t.has);
  teams.forEach((t) =>
    t.slots.forEach((sl) => {
      if (sl.gaps >= 2)
        issues.push({
          key: `gap|${t.team}|${sl.slot}`, level: "warn", who: `${t.emoji} ${t.team.replace("Team ", "")} · ${sl.slot}`, emp: null,
          text: `${sl.gaps} day${sl.gaps === 1 ? "" : "s"} with nobody clocked in on this slot.`,
        });
    })
  );
  employees.forEach((e) => {
    const worked = e.shifts.some((sh) => num(sh.hours) > 0 || num(sh.revenue) > 0);
    if (worked && e.name.trim() && !rosterLookup(e.name, roster))
      issues.push({ key: `offroster|${e.id}`, level: "info", who: e.name, emp: e, text: "Not on the roster — add them so coverage can count them." });
  });
  issues.sort((a, b) => (a.level === b.level ? 0 : a.level === "warn" ? -1 : 1));
  const totalGaps = teams.reduce((a, t) => a + t.slots.reduce((b, sl) => b + sl.gaps, 0), 0);
  return { start, end, days, perPerson, teams, issues, totalGaps };
}

// rule-based coaching pointers from this week's stats
function buildInsights(emp, employees, settings) {
  const c = calcEmployee(emp, settings);
  const tiers = resolveSettings(settings, emp).tiers;
  const worked = emp.shifts
    .map((s, i) => ({ s, k: c.shiftCalcs[i] }))
    .filter((x) => x.k.hours > 0 || x.k.revenue > 0);
  const n = worked.length;
  if (!n) return null;
  const avgRev = c.totalRevenue / n;
  const rph = c.totalHours > 0 ? c.totalRevenue / c.totalHours : 0;
  const hits = worked.filter((x) => x.k.tier >= 0).length;
  const best = worked.reduce((a, b) => (b.k.revenue > a.k.revenue ? b : a));
  const worst = worked.reduce((a, b) => (b.k.revenue < a.k.revenue ? b : a));
  const resps = worked.map((x) => num(x.s.respMin)).filter((v) => v > 0);
  const avgResp = resps.length
    ? resps.reduce((a, b) => a + b, 0) / resps.length
    : null;
  const sched = worked.reduce((a, x) => a + num(x.s.schedHours), 0);
  const ppvSent = worked.reduce((a, x) => a + num(x.s.ppvSent), 0);
  const msgsSent = worked.reduce((a, x) => a + num(x.s.msgsSent), 0);
  const ppvUnlocked = worked.reduce((a, x) => a + num(x.s.ppvUnlocked), 0);
  // Infloww's "Hours on Messages Pro": time actually spent in the inbox
  const mpHours = round2(worked.reduce((a, x) => a + num(x.s.mpHours), 0));
  const fansChatted = worked.reduce((a, x) => a + num(x.s.fansChatted), 0);
  const clocked = c.totalHours;
  const per = (v, h) => (h > 0 ? v / h : null);
  const mp = {
    hours: mpHours,
    share: mpHours > 0 && clocked > 0 ? (mpHours / clocked) * 100 : null,
    salesPerHour: per(c.totalRevenue, mpHours),
    msgsPerHour: per(msgsSent, mpHours),
    fansPerHour: per(fansChatted, mpHours),
    salesPerClock: per(c.totalRevenue, clocked),
    msgsPerClock: per(msgsSent, clocked),
    fansPerClock: per(fansChatted, clocked),
  };
  const goldenRatio = msgsSent > 0 ? (ppvSent / msgsSent) * 100 : null;
  const unlockRate = ppvSent > 0 ? (ppvUnlocked / ppvSent) * 100 : null;
  const teamMates = employees.filter(
    (e) => (e.team || "") === (emp.team || "")
  );
  const ranked = teamMates
    .map((e) => {
      const ce = e.id === emp.id ? c : calcEmployee(e, settings);
      const mph = e.shifts.reduce((a, s) => a + num(s.mpHours), 0);
      return {
        id: e.id,
        rph: ce.totalHours > 0 ? ce.totalRevenue / ce.totalHours : 0,
        mpRph: mph > 0 ? ce.totalRevenue / mph : 0,
      };
    })
    .filter((r) => r.rph > 0)
    .sort((a, b) => b.rph - a.rph);
  const rank = ranked.findIndex((r) => r.id === emp.id) + 1;
  const teamAvgRph = ranked.length
    ? ranked.reduce((a, r) => a + r.rph, 0) / ranked.length
    : 0;

  const wins = [];
  const tips = [];

  if (avgRev >= tiers[2].threshold) {
    wins.push(
      `Elite week — averaging ${fmt(avgRev)}/shift, above Target 3. Keep the playbook exactly as is.`
    );
  } else if (avgRev >= tiers[0].threshold) {
    const nextIdx = avgRev >= tiers[1].threshold ? 2 : 1;
    wins.push(
      `Solid earner — averaging ${fmt(avgRev)}/shift (Target ${avgRev >= tiers[1].threshold ? 2 : 1} pace).`
    );
    tips.push({
      t: `Push to Target ${nextIdx + 1}`,
      b: `Only ${fmt(tiers[nextIdx].threshold - avgRev)} more per shift unlocks ${fmt(tiers[nextIdx].rate)}/hr + ${tiers[nextIdx].commission}% commission. Upsell right after each purchase — bundles or the next content tier while excitement is high.`,
    });
  } else {
    tips.push({
      t: "Close the gap to Target 1",
      b: `Averaging ${fmt(avgRev)}/shift — ${fmt(tiers[0].threshold - avgRev)} short of Target 1 (${fmt(tiers[0].rate)}/hr + ${tiers[0].commission}%). Build value before every PPV and follow up unopened ones before shift end instead of letting them sit.`,
    });
  }
  if (n >= 3 && best.k.revenue > 0 && worst.k.revenue < best.k.revenue * 0.4) {
    tips.push({
      t: "Consistency",
      b: `Best shift${best.s.date ? ` (${best.s.date})` : ""} did ${fmt(best.k.revenue)} but the slowest did ${fmt(worst.k.revenue)}. On quiet shifts, spend the first hour re-engaging lapsed spenders with personal openers instead of waiting for traffic.`,
    });
  }
  if (rank === 1 && ranked.length > 1) {
    wins.push(`Top of ${emp.team || "the board"} at ${fmt(rph)}/hr.`);
  } else if (teamAvgRph > 0 && rph > 0 && rph < teamAvgRph * 0.8) {
    tips.push({
      t: "Revenue per hour",
      b: `${fmt(rph)}/hr vs. a team average of ${fmt(teamAvgRph)}/hr. Prioritize top spenders and hot conversations first, then online fans — not whoever messaged last.`,
    });
  }
  // time on Messages Pro vs clocked: below 70% means they're clocked in but not in the inbox
  if (mp.share != null) {
    if (mp.share < 70) {
      tips.push({
        t: "Time on Messages Pro",
        b: `Only ${mp.hours}h of ${round2(clocked)}h clocked were spent in Messages Pro (${mp.share.toFixed(0)}% — below the 70% line). Clocked time outside the inbox earns nothing: check for breaks, tab-switching or idle shifts, and set the expectation that clocked means chatting.`,
      });
    } else if (mp.share >= 90) {
      wins.push(`Locked in — ${mp.share.toFixed(0)}% of clocked time spent in Messages Pro.`);
    }
  }
  if (mp.salesPerHour != null) {
    const peers = ranked.filter((r) => r.mpRph > 0);
    const teamMp = peers.length ? peers.reduce((a, r) => a + r.mpRph, 0) / peers.length : 0;
    if (peers.length > 1 && teamMp > 0 && mp.salesPerHour < teamMp * 0.8) {
      tips.push({
        t: "Sales per Messages Pro hour",
        b: `${fmt(mp.salesPerHour)} per hour in the inbox vs. a team average of ${fmt(teamMp)}. Time isn't the problem — conversion is. ${mp.fansPerHour != null && mp.fansPerHour < 3 ? `They're reaching ${mp.fansPerHour.toFixed(1)} fans an hour; widen the net with openers to recent spenders.` : "Pitch earlier in the conversation and follow up unopened PPVs before moving on."}`,
      });
    } else if (peers.length > 1 && teamMp > 0 && mp.salesPerHour >= teamMp * 1.2) {
      wins.push(`${fmt(mp.salesPerHour)} per Messages Pro hour — ${((mp.salesPerHour / teamMp - 1) * 100).toFixed(0)}% above the team.`);
    }
  }
  if (avgResp != null) {
    if (avgResp > 5) {
      tips.push({
        t: "Response speed",
        b: `Averaging ${avgResp.toFixed(1)} min per reply this week. Aim under 3 — send quick holding replies when juggling several fans so nobody goes cold.`,
      });
    } else if (avgResp <= 3) {
      wins.push(`Fast replies — ${avgResp.toFixed(1)} min average response time.`);
    }
  }
  if (sched > 0 && c.totalHours < sched * 0.85) {
    tips.push({
      t: "Hours & attendance",
      b: `Clocked ${c.totalHours}h of ${round2(sched)}h scheduled. Full shifts protect the team goal and their own hourly pay — worth a direct conversation about the gaps.`,
    });
  }
  if (goldenRatio != null) {
    if (goldenRatio < 5) {
      tips.push({
        t: "Golden ratio",
        b: `${goldenRatio.toFixed(1)}% — only ${ppvSent} PPVs across ${msgsSent} messages. They're chatting without pitching; aim for roughly 1 PPV per 12–15 messages by steering conversations toward content.`,
      });
    } else if (goldenRatio >= 8) {
      wins.push(
        `Healthy golden ratio — ${goldenRatio.toFixed(1)}% (${ppvSent} PPVs / ${msgsSent} messages).`
      );
    }
  }
  if (unlockRate != null && ppvSent >= 10) {
    if (unlockRate < 30) {
      tips.push({
        t: "PPV unlock rate",
        b: `Only ${unlockRate.toFixed(0)}% of ${ppvSent} PPVs unlocked. Build more value before sending — tease, describe, anchor the price — and check they aren't opening at ceiling prices.`,
      });
    } else if (unlockRate >= 45) {
      wins.push(`Strong PPV conversion — ${unlockRate.toFixed(0)}% unlock rate.`);
    }
  }
  if (c.strikes >= 2) {
    tips.push({
      t: "Strike recovery",
      b: `${c.strikes} strikes — weekly bonuses paused${c.monthlyForfeited ? ", monthly bonus paused" : ""}${c.commissionPenalty ? ", commission down 1%" : ""}. Agree on 1–2 focus areas and a follow-up date so there's a clear path back to full pay.`,
    });
  }
  if (!tips.length) wins.push("No red flags this week.");
  return {
    n,
    avgRev,
    rph,
    hits,
    avgResp,
    rank,
    teamSize: ranked.length,
    clocked: c.totalHours,
    ppvSent,
    msgsSent,
    fansChatted,
    mp,
    goldenRatio,
    unlockRate,
    wins,
    tips,
  };
}

// full-team ranking report with team-level tips
function buildTeamReport(team, employees, settings) {
  const members = employees
    .filter((e) => (e.team || "") === (team || ""))
    .map((e) => {
      const c = calcEmployee(e, settings);
      const ins = buildInsights(e, employees, settings);
      const worked = c.shiftCalcs.filter((k) => k.hours > 0 || k.revenue > 0);
      return {
        e,
        c,
        ins,
        shifts: worked.length,
        rev: c.totalRevenue,
        rph: c.totalHours > 0 ? c.totalRevenue / c.totalHours : 0,
        avgRev: worked.length ? c.totalRevenue / worked.length : 0,
        hits: worked.filter((k) => k.tier >= 0).length,
        hours: c.totalHours,
        ppv: e.shifts.reduce((a, s) => a + num(s.ppvSent), 0),
        msgs: e.shifts.reduce((a, s) => a + num(s.msgsSent), 0),
        unlocked: e.shifts.reduce((a, s) => a + num(s.ppvUnlocked), 0),
        mpHours: e.shifts.reduce((a, s) => a + num(s.mpHours), 0),
        fans: e.shifts.reduce((a, s) => a + num(s.fansChatted), 0),
        topTip: ins && ins.tips.length ? ins.tips[0].t : null,
      };
    })
    .filter((m) => m.shifts > 0)
    .sort((a, b) => b.rev - a.rev);
  if (!members.length) return null;
  const totalRev = members.reduce((a, m) => a + m.rev, 0);
  const totalHours = members.reduce((a, m) => a + m.c.totalHours, 0);
  const totalShifts = members.reduce((a, m) => a + m.shifts, 0);
  const totalHits = members.reduce((a, m) => a + m.hits, 0);
  const teamRph = totalHours > 0 ? totalRev / totalHours : 0;
  const teamAvgShift = totalShifts ? totalRev / totalShifts : 0;
  const teamPpv = members.reduce((a, m) => a + m.ppv, 0);
  const teamMsgs = members.reduce((a, m) => a + m.msgs, 0);
  const teamUnlocked = members.reduce((a, m) => a + m.unlocked, 0);
  const teamGr = teamMsgs > 0 ? (teamPpv / teamMsgs) * 100 : null;
  const teamUnlockRate = teamPpv > 0 ? (teamUnlocked / teamPpv) * 100 : null;
  const tiers = tiersFor(settings, team);
  const tips = [];
  const wins = [];
  const flags = {
    belowT1: false,
    spread: false,
    strikers: [],
    slowResp: false,
    lowGR: false,
    lowUnlock: false,
  };
  if (teamAvgShift < tiers[0].threshold) {
    flags.belowT1 = true;
    tips.push(
      `Team averages ${fmt(teamAvgShift)}/shift — below Target 1 (${fmt(tiers[0].threshold)}). Run a group session on PPV value-building and unopened follow-ups, and consider whether the targets fit this account's current traffic.`
    );
  }
  if (
    members.length >= 2 &&
    members[members.length - 1].rph < members[0].rph * 0.5
  ) {
    flags.spread = true;
    tips.push(
      `Big spread: ${members[0].e.name} earns ${fmt(members[0].rph)}/hr while the bottom is at ${fmt(members[members.length - 1].rph)}/hr. Have the top earner share their approach in team chat or shadow a shift handoff.`
    );
  }
  const strikers = members.filter((m) => m.c.strikes >= 2);
  if (strikers.length) {
    flags.strikers = strikers.map((m) => m.e.name);
    tips.push(
      `${strikers.length} chatter${strikers.length > 1 ? "s" : ""} at 2+ strikes (${strikers.map((m) => m.e.name).join(", ")}) — schedule reviews so bonuses come back within reach.`
    );
  }
  const idle = members.filter((m) => m.mpHours > 0 && m.hours > 0 && m.mpHours < m.hours * 0.7);
  if (idle.length) {
    flags.idle = idle.map((m) => m.e.name);
    tips.push(
      `${idle.length} chatter${idle.length > 1 ? "s" : ""} under 70% of clocked time on Messages Pro (${idle.map((m) => `${m.e.name} ${((m.mpHours / m.hours) * 100).toFixed(0)}%`).join(", ")}). Clocked hours are being paid for time outside the inbox — review those shifts before approving pay.`
    );
  }
  if (teamGr != null && teamGr < 5) {
    flags.lowGR = true;
    tips.push(
      `Team golden ratio is ${teamGr.toFixed(1)}% — the team is chatting without pitching. Set a shared benchmark of roughly 1 PPV per 12–15 messages.`
    );
  }
  if (teamUnlockRate != null && teamPpv >= 20 && teamUnlockRate < 30) {
    flags.lowUnlock = true;
    tips.push(
      `Team unlock rate is ${teamUnlockRate.toFixed(0)}% — PPVs aren't converting. Review pricing ladders and value-building before sends at the next team meeting.`
    );
  }
  const respAll = members
    .map((m) => (m.ins ? m.ins.avgResp : null))
    .filter((v) => v != null);
  const avgRespTeam = respAll.length
    ? respAll.reduce((a, b) => a + b, 0) / respAll.length
    : null;
  if (avgRespTeam != null && avgRespTeam > 5) {
    flags.slowResp = true;
    tips.push(
      "Replies are slow across the team — set a shared under-3-minute response goal and use quick holding replies during rush periods."
    );
  }
  if (totalShifts > 0 && totalHits / totalShifts >= 0.6 && teamAvgShift >= tiers[0].threshold) {
    tips.push(
      `Strong week — ${totalHits} of ${totalShifts} shifts hit a target. Worth a shoutout in the team chat.`
    );
  }
  if (!tips.length) {
    tips.push(
      "No team-wide issues detected this week — handle the individual focus areas in each chatter's Insights tab."
    );
  }
  // what the team is doing well
  if (teamAvgShift >= tiers[1].threshold) {
    wins.push(
      `Averaging ${fmt(teamAvgShift)}/shift — Target ${teamAvgShift >= tiers[2].threshold ? 3 : 2} pace as a team.`
    );
  } else if (teamAvgShift >= tiers[0].threshold) {
    wins.push(`Averaging ${fmt(teamAvgShift)}/shift — above Target 1 as a team.`);
  }
  if (teamGr != null && teamGr >= 7)
    wins.push(`Strong pitch frequency — team golden ratio ${teamGr.toFixed(1)}%.`);
  if (teamUnlockRate != null && teamUnlockRate >= 40)
    wins.push(`PPVs convert well — ${teamUnlockRate.toFixed(0)}% unlock rate.`);
  if (avgRespTeam != null && avgRespTeam <= 3.5)
    wins.push(`Fast replies — ${avgRespTeam.toFixed(1)} min team average.`);
  if (totalShifts > 0 && totalHits / totalShifts >= 0.5)
    wins.push(`${totalHits} of ${totalShifts} shifts hit a target.`);
  wins.push(`Top earner: ${members[0].e.name} (${fmt(members[0].rev)}).`);
  return {
    members,
    totalRev,
    teamRph,
    teamAvgShift,
    totalShifts,
    totalHits,
    totalHours,
    teamPpv,
    teamMsgs,
    teamGr,
    teamUnlockRate,
    avgRespTeam,
    tips,
    wins,
    flags,
  };
}

function calcShift(shift, settings, headChatter, commissionPenalty = 0) {
  const hours = num(shift.hours);
  const ofRevenue = num(shift.revenue);
  const fanslyRevenue = num(shift.fansly);
  const revenue = ofRevenue + fanslyRevenue; // gross — drives tiers and all stats
  // net of the platform's cut; this is what commission is paid on
  const cutPct = (v) => Math.min(100, Math.max(0, num(v))) / 100;
  const ofNet = ofRevenue * (1 - cutPct(settings.ofCut));
  const fanslyNet = fanslyRevenue * (1 - cutPct(settings.fanslyCut));
  const netRevenue = ofNet + fanslyNet;
  const tier = getTier(revenue, settings.tiers);
  const baseHourly = tier === -1 ? settings.baseRate : settings.tiers[tier].rate;
  const commissionPct = Math.max(
    0,
    (tier === -1 ? settings.baseCommission : settings.tiers[tier].commission) -
      commissionPenalty
  );
  // streaming bump applies only to streamed hours; blank = whole shift
  const streamHours = shift.streaming
    ? shift.streamHours === "" || shift.streamHours == null
      ? hours
      : Math.min(num(shift.streamHours), hours)
    : 0;
  const rate = baseHourly;
  const streamPay = streamHours * settings.streamingBump;
  const hourlyPay = hours * rate + streamPay;
  const commissionPay = netRevenue * (commissionPct / 100);
  return {
    tier,
    rate,
    commissionPct,
    hourlyPay,
    commissionPay,
    total: hourlyPay + commissionPay,
    hours,
    streamHours: round2(streamHours),
    streamPay,
    revenue,
    netRevenue,
    ofRevenue,
    fanslyRevenue,
    ofNet,
    fanslyNet,
  };
}

