// ---------- goal & target recommendations ----------
// Everything here is a suggestion: it reads what actually sold and proposes
// numbers that stretch without being out of reach. Nothing applies itself.
const niceStep = (v) => (v >= 20000 ? 1000 : v >= 5000 ? 500 : v >= 1000 ? 250 : v >= 300 ? 50 : 25);
const niceRound = (v, step) => Math.round(v / (step || niceStep(v))) * (step || niceStep(v));

// series: weekly totals oldest → newest, current week last
function recommendGoal(series, currentWeekly) {
  const pts = (series || []).filter((v) => v > 0);
  if (!pts.length) return null;
  const recent = pts.slice(-4);
  const weights = recent.map((_, i) => i + 1); // newest counts most
  const avg =
    recent.reduce((a, v, i) => a + v * weights[i], 0) /
    weights.reduce((a, b) => a + b, 0);
  const first = recent[0];
  const last = recent[recent.length - 1];
  const slope = recent.length >= 2 ? (last - first) / (recent.length - 1) / Math.max(1, avg) : 0;
  let stretch = 0.1;
  let mood = "steady";
  if (slope > 0.05) { stretch = 0.15; mood = "climbing"; }
  if (slope < -0.05) { stretch = 0.05; mood = "slipping"; }
  let weekly = avg * (1 + stretch);
  const cur = num(currentWeekly);
  if (cur > 0) {
    // no whiplash: move at most a quarter of the way per review
    weekly = Math.min(weekly, cur * 1.25);
    weekly = Math.max(weekly, cur * 0.75);
  }
  weekly = niceRound(weekly);
  const monthly = niceRound(weekly * 4);
  const hits = cur > 0 ? recent.filter((v) => v >= cur).length : null;
  const parts = [
    `avg ${fmt0(avg)} over ${recent.length} wk${recent.length === 1 ? "" : "s"}`,
    recent.length >= 2 ? mood : null,
    `+${Math.round(stretch * 100)}% stretch`,
    cur > 0 ? `hit current ${hits}/${recent.length}` : null,
  ].filter(Boolean);
  return { weekly, monthly, avg, weeks: recent.length, mood, stretch, hits, reason: parts.join(" · ") };
}

// shift-level gross revenue → three thresholds that about half / a third / a
// tenth of shifts would clear, pulled toward the current targets
function recommendTiers(shiftRevs, currentTiers) {
  const vals = (shiftRevs || []).filter((v) => v > 0).sort((a, b) => a - b);
  const n = vals.length;
  const cur = (currentTiers || []).map((t) => num(t.threshold));
  const clear = (th) => (n ? vals.filter((v) => v >= th).length / n : 0);
  const hitPct = cur.map(clear);
  if (n < 6) {
    return { ok: false, n, hitPct, note: `Need at least 6 shifts to suggest targets (have ${n}).` };
  }
  const q = (p) => {
    const pos = p * (n - 1);
    const lo = Math.floor(pos);
    const hi = Math.min(n - 1, lo + 1);
    return vals[lo] + (vals[hi] - vals[lo]) * (pos - lo);
  };
  const tooEasy = hitPct[0] >= 0.85 && hitPct[2] >= 0.5;
  const tooHard = hitPct[0] <= 0.2;
  let t = [q(0.45), q(0.7), q(0.88)];
  t = t.map((v, i) => {
    // nudge gently when targets are roughly right; jump to the data when they're clearly off
    if (cur[i] > 0 && !tooEasy && !tooHard) v = Math.max(cur[i] * 0.7, Math.min(cur[i] * 1.3, v));
    return niceRound(v, 50);
  });
  for (let i = 1; i < 3; i++) t[i] = Math.max(t[i], t[i - 1] + 100);
  const after = t.map(clear);
  const verdict = tooEasy
    ? "Too easy — most shifts clear even Target 3."
    : tooHard
      ? "Too hard — almost no shifts clear Target 1."
      : hitPct[2] >= 0.35
        ? "Target 3 is cleared too often to feel like a stretch."
        : "Roughly in range — small tune-up.";
  const changed = t.some((v, i) => v !== cur[i]);
  const lower = t[0] < cur[0];
  return { ok: true, n, thresholds: t, hitPct, after, median: q(0.5), verdict, changed, lower };
}

// one plan for everything: teams, models and shift targets
function buildGoalPlan(employees, settings, history) {
  const hist = (history || []).slice(-6);
  const teamNames = TEAM_DEFS.map((t) => t.team).filter((team) =>
    employees.some((e) => e.team === team) ||
    hist.some((h) => h.teams && h.teams[team] && h.teams[team].rev > 0) ||
    goalFor(settings, team, "weekly") > 0
  );
  const teams = teamNames.map((team) => {
    const r = buildTeamReport(team, employees, settings);
    const series = hist.map((h) => (h.teams && h.teams[team] ? num(h.teams[team].rev) : 0));
    series.push(r ? r.totalRev : 0);
    const current = { weekly: goalFor(settings, team, "weekly"), monthly: goalFor(settings, team, "monthly") };
    return { team, current, thisWeek: r ? r.totalRev : 0, rec: recommendGoal(series, current.weekly) };
  });

  const mr = buildModelReport(employees, settings);
  const modelNames = new Set(Object.keys(settings.modelGoalAmounts || {}));
  if (mr) mr.rows.forEach((r) => r.name !== "Unattributed" && modelNames.add(r.name));
  hist.forEach((h) => h.models && Object.keys(h.models).forEach((m) => m !== "Unattributed" && modelNames.add(m)));
  const creatorRep = latestCreatorReport(settings);
  if (creatorRep) creatorRep.creators.forEach((c) => modelNames.add(c.name));
  const models = [...modelNames].map((model) => {
    const row = mr && mr.rows.find((r) => r.name === model);
    // Infloww creator reports (net, 14-day) become weekly-equivalent points first;
    // the chatter-attributed weeks follow — the newest point weighs most
    const fromReports = creatorWeeklySeries(settings, model).filter((v) => v > 0);
    const series = fromReports.concat(hist.map((h) => (h.models && h.models[model] ? num(h.models[model].rev) : 0)));
    series.push(row ? row.revenue : 0);
    const current = { weekly: modelGoalFor(settings, model, "weekly"), monthly: modelGoalFor(settings, model, "monthly") };
    return { model, current, thisWeek: row ? row.revenue : 0, rec: recommendGoal(series, current.weekly) };
  }).sort((a, b) => b.thisWeek - a.thisWeek);

  const revsFor = (team) => {
    const out = [];
    employees
      .filter((e) => team === "" || (e.team || "") === team)
      .forEach((e) => {
        calcEmployee(e, settings).shiftCalcs.forEach((k) => k.revenue > 0 && out.push(k.revenue));
      });
    hist.slice(-3).forEach((h) => {
      if (!h.teams) return;
      if (team === "") Object.values(h.teams).forEach((t) => (t.shiftRevs || []).forEach((v) => out.push(v)));
      else if (h.teams[team]) (h.teams[team].shiftRevs || []).forEach((v) => out.push(v));
    });
    return out;
  };
  const tiers = ["", ...teamNames].map((team) => {
    const current = tiersFor(settings, team);
    return { team, current, rec: recommendTiers(revsFor(team), current) };
  });
  return { teams, models, tiers };
}
