const nameKey = (v) =>
  String(v || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9 ]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
function rosterLookup(name, roster = null) {
  const n = nameKey(name);
  if (!n) return null;
  const list = roster || LIVE_ROSTER || DEFAULT_ROSTER;
  const first = n.split(" ")[0];
  const exact = list.find(([rn]) => nameKey(rn) === n);
  if (exact) return rosterRow(exact);
  if (n.length < 3) return null;
  // "Flor" ↔ "Flor Mae", "Katelyn R" ↔ "Katelyn": same first name, or one is a prefix of the other
  const loose = list.filter(([rn]) => {
    const r = nameKey(rn);
    const rf = r.split(" ")[0];
    return r.startsWith(n) || n.startsWith(r) || (rf.length >= 3 && rf === first);
  });
  return loose.length === 1 ? rosterRow(loose[0]) : loose.length > 1 ? rosterRow(loose.find(([rn]) => nameKey(rn).split(" ")[0] === first) || loose[0]) : null;
}
