const rosterRow = (r) => ({
  name: r[0],
  team: r[1],
  slot: r[2],
  start: r[3] || "",
  status: r[4] || "active",
  days: r[5] === undefined || r[5] === "" ? 6 : num(r[5]),
});
const tenureLabel = (start, settings) => {
  if (!start) return "";
  const a = new Date(start + "T00:00:00");
  const b = new Date(todayStr(settings) + "T00:00:00");
  if (isNaN(a) || isNaN(b)) return "";
  const months = Math.max(0, Math.round((b - a) / (1000 * 60 * 60 * 24 * 30.4)));
  if (months < 1) return "new this month";
  if (months < 12) return `${months} mo`;
  const y = Math.floor(months / 12);
  const m = months % 12;
  return `${y} yr${y > 1 ? "s" : ""}${m ? ` ${m} mo` : ""}`;
};
