// ---------- Infloww parsing ----------
// Finds the best sheet and maps rows to {name, date, hours, revenue}
function parseInflowwWorkbook(wb, hoursSource) {
  // Prefer the per-day sheet so each row = one shift
  const preferred = wb.SheetNames.find((n) =>
    n.toLowerCase().includes("time")
  );
  const sheetName = preferred || wb.SheetNames[0];
  const rows = XLSX.utils.sheet_to_json(wb.Sheets[sheetName], {
    defval: "",
    raw: false,
  });
  if (!rows.length) return { sheetName, shifts: [], skipped: 0 };

  const headers = Object.keys(rows[0]);
  const find = (...keys) =>
    headers.find((h) => keys.some((k) => h.toLowerCase().includes(k)));
  // exact match first, then a header that STARTS with the phrase —
  // avoids grabbing "Response time (based on clocked hours)"
  const findHours = (phrase) =>
    headers.find((h) => h.toLowerCase().trim() === phrase) ||
    headers.find((h) => h.toLowerCase().trim().startsWith(phrase));

  const colName = find("employee");
  const colGroup = find("group");
  const colDate = find("date/time", "date");
  // Infloww names the export's zone in the header: "Date/Time America/Chicago".
  // "Date/Time" itself looks like a zone, so take the first candidate that is one.
  const tzHits = String(colDate || "").match(/[A-Za-z]+\/[A-Za-z_+-]+/g) || [];
  const exportTz = tzHits.find((t) => tzValid(t)) || "";
  const colSales = headers.find((h) => h.toLowerCase().trim() === "sales") ||
    find("sales");
  const colClocked = findHours("clocked hours");
  const colScheduled = findHours("scheduled hours");
  const colResp =
    headers.find((h) =>
      h.toLowerCase().startsWith("response time (based on clocked")
    ) || headers.find((h) => h.toLowerCase().startsWith("response time"));
  const exactCol = (name) =>
    headers.find((h) => h.toLowerCase().trim() === name);
  const colCreators = exactCol("creators") || find("creator");
  const colPpv = exactCol("direct ppvs sent") || find("ppvs sent");
  const colMsgs = exactCol("direct messages sent") || exactCol("messages sent") || find("messages sent");
  const colUnlocked = exactCol("ppvs unlocked") || find("ppvs unlocked");
  // Infloww (late 2026): time actually spent inside Messages Pro, and fans chatted —
  // the per-hour columns are recomputed here from the totals, so they stay right
  // when several shifts are summed.
  const colMp = findHours("hours on messages pro") || find("hours on messages pro", "messages pro hours");
  const colFans = exactCol("fans chatted") || find("fans chatted");
  const colHours =
    hoursSource === "scheduled"
      ? colScheduled || colClocked
      : colClocked || colScheduled;

  const shifts = [];
  let skipped = 0;
  rows.forEach((r) => {
    const name = String(r[colName] || "").trim();
    if (!name) return;
    const hours = parseDuration(r[colHours]);
    const revenue = parseMoney(r[colSales]);
    if (hours === 0 && revenue === 0) {
      skipped++;
      return; // no shift worked
    }
    shifts.push({
      name,
      group: String(r[colGroup] || "").trim(),
      date: parseDateRange(r[colDate]),
      hours: round2(hours),
      revenue: round2(revenue),
      schedHours: colScheduled ? round2(parseDuration(r[colScheduled])) : 0,
      respMin: colResp ? round2(parseRespMinutes(r[colResp])) : 0,
      creators: colCreators ? String(r[colCreators] || "").trim() : "",
      ppvSent: colPpv ? parseMoney(r[colPpv]) : 0,
      msgsSent: colMsgs ? parseMoney(r[colMsgs]) : 0,
      ppvUnlocked: colUnlocked ? parseMoney(r[colUnlocked]) : 0,
      mpHours: colMp ? round2(parseDuration(r[colMp])) : 0,
      fansChatted: colFans ? parseMoney(r[colFans]) : 0,
    });
  });
  return { sheetName, shifts, skipped, exportTz, sheetNames: wb.SheetNames, hasMp: !!colMp };
}

