// ---------- saving files ----------
// The downloaded .html saves straight to the browser's Downloads folder. The
// hosted app runs in a sandbox that can't start downloads itself, so it hands
// the file to the viewer's save prompt instead (they can decline).
const isHosted = () =>
  typeof window !== "undefined" && !!window.claude && typeof window.claude.use === "function";
async function saveFile(filename, data) {
  if (isHosted()) {
    const dl = await window.claude.use("downloads");
    if (dl) {
      try {
        await dl.save({ filename, data });
        return true;
      } catch (err) {
        if (err && err.code === "declined") return false;
        throw err;
      }
    }
  }
  const blob = data instanceof Blob ? data : new Blob([data]);
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = filename;
  a.click();
  setTimeout(() => URL.revokeObjectURL(a.href), 4000);
  return true;
}
// pptxgenjs → blob (the hosted app can't use writeFile)
const pptxBlob = (pptx) => pptx.write({ outputType: "blob" });

const fmt0 = (v) => "$" + Math.round(num(v)).toLocaleString();
const pct0 = (v) => Math.round((v || 0) * 100) + "%";

// a compact "💡 suggested" pill with a Use button
function SuggestChip({ rec, current, onUse, compact }) {
  if (!rec) return null;
  const same = num(current.weekly) === rec.weekly && num(current.monthly) === rec.monthly;
  return (
    <div
      className={`flex flex-wrap items-center gap-x-2 gap-y-1 rounded-lg border px-2.5 py-1.5 ${
        same ? "border-emerald-100 bg-emerald-50/60" : "border-yellow-200 bg-yellow-50"
      }`}
    >
      <span className="text-[11px] font-bold text-slate-700">
        💡 {fmt0(rec.weekly)} wk · {fmt0(rec.monthly)} mo
      </span>
      {!compact && <span className="text-[10.5px] text-slate-500">{rec.reason}</span>}
      {same ? (
        <span className="text-[10.5px] font-bold text-emerald-700 ml-auto">✓ matches</span>
      ) : (
        <button
          onClick={onUse}
          className="ml-auto rounded-full bg-slate-900 text-white px-2.5 py-0.5 text-[11px] font-bold hover:bg-pink-600"
        >
          Use
        </button>
      )}
    </div>
  );
}

// one editable goal line: label · this week · weekly · monthly · suggestion
function GoalRow({ label, sub, thisWeek, weekly, monthly, onChange, rec, showRec, onUse }) {
  const w = num(weekly);
  const pct = w > 0 ? Math.min(100, (thisWeek / w) * 100) : 0;
  const hit = w > 0 && thisWeek >= w;
  return (
    <div className="rounded-xl border border-pink-100 bg-white p-3">
      <div className="flex flex-wrap items-end gap-x-3 gap-y-2">
        <div className="flex-1 min-w-[160px] self-center">
          <p className="text-sm font-bold text-slate-900 leading-tight">{label}</p>
          <p className="text-[11px] text-slate-500 tabular mt-0.5">
            {sub ? sub + " · " : ""}this week {fmt0(thisWeek)}
            {w > 0 && (
              <span className={hit ? " text-emerald-700 font-bold" : ""}>
                {" "}· {Math.round((thisWeek / w) * 100)}% of weekly
              </span>
            )}
          </p>
        </div>
        <label className="block w-28">
          <span className="block text-[10px] font-bold uppercase tracking-[.08em] text-slate-400 mb-1">Weekly ($)</span>
          <input
            type="number"
            step="100"
            min="0"
            className={inputCls}
            value={weekly || ""}
            placeholder="0"
            onChange={(e) => onChange("weekly", e.target.value)}
          />
        </label>
        <label className="block w-28">
          <span className="block text-[10px] font-bold uppercase tracking-[.08em] text-slate-400 mb-1">Monthly ($)</span>
          <input
            type="number"
            step="500"
            min="0"
            className={inputCls}
            value={monthly || ""}
            placeholder="0"
            onChange={(e) => onChange("monthly", e.target.value)}
          />
        </label>
        {showRec && rec && (
          <div className="basis-full xl:basis-auto xl:flex-1 xl:min-w-[300px]">
            <SuggestChip rec={rec} current={{ weekly, monthly }} onUse={onUse} />
          </div>
        )}
      </div>
      {w > 0 && (
        <div className="h-1.5 mt-2.5 rounded-full bg-pink-50 overflow-hidden">
          <div className={`ss-bar h-full ${hit ? "bg-emerald-500" : "bg-pink-500"}`} style={{ width: pct + "%" }} />
        </div>
      )}
    </div>
  );
}

